func (x *isolationRun) revoke() {
	r := x.a2
	c := iso.Check{Name: "revoke established TCP and UDP", Positive: x.proof(r), Owner: "w2-agent-core / w3-wire-members"}
	path := "/tmp/isolation-revoke.json"
	e := exec.Command("docker", "exec", "-d", r.lab.member, "/tmp/isolation-probe", "stream", r.originIP(), "45", path).Run()
	time.Sleep(2 * time.Second)
	before, _ := r.lab.docker(r.lab.member, "cat", path)
	c.Observations = append(c.Observations, iso.Observation{Name: "stream_before", Detail: string(before)})
	source := memberIP(r)
	ctBefore, ctBeforeErr := r.lab.docker(r.lab.node, "conntrack", "-L", "-s", source, "-d", r.originIP(), "-o", "extended")
	old := r.lab.forwardChain().Generation
	memberSession, err := r.lab.login(x.ctx, "iso-a", "member")
	if err != nil {
		c.Status = iso.StatusBlocked
		c.Actual = "member session refresh failed"
		x.add("AT13", c)
		return
	}
	x.a = memberSession
	deleteStarted := time.Now().UTC()
	resp, err := x.a.call(x.ctx, "DELETE", r.lab.public+"/api/v1/member/devices/"+r.usageDevice.String(), nil, map[string]string{"Idempotency-Key": uuid.NewString()})
	deleteCompleted := time.Now().UTC()
	c.Observations = append(c.Observations, iso.Observation{Name: "delete", Detail: httpDetail(resp, err)})
	wait, cancel := context.WithTimeout(x.ctx, 90*time.Second)
	applied := waitUntil(wait, time.Second, func() bool {
		_, bound := readProjectedBinding(r.desiredRaw(), r.usageDevice)
		return !bound && r.lab.forwardChain().Generation > old && r.lab.forwardChain().MemberAccept > 0
	})
	cancel()
	time.Sleep(3 * time.Second)
	after, _ := r.lab.docker(r.lab.member, "cat", path)
	ctAfter, ctAfterErr := r.lab.docker(r.lab.node, "conntrack", "-L", "-s", source, "-d", r.originIP(), "-o", "extended")
	x.extra("revocation-request.json", map[string]any{"run_id": x.records["AT13"].RunID, "device_id": r.usageDevice, "old_generation": old, "request_started": deleteStarted, "response_completed": deleteCompleted, "response_status": resp.Status, "stream_before": json.RawMessage(before), "stream_after": json.RawMessage(after), "conntrack_after_read": time.Now().UTC(), "scope": "HTTP request/response and established-flow failures; desired delivery and restricting install joined separately to producer, including pre-Apply reservation"})
	var a, b struct {
		TCP     int    `json:"tcp_ok"`
		UDP     int    `json:"udp_ok"`
		TCPFail string `json:"tcp_first_fail"`
		UDPFail string `json:"udp_first_fail"`
	}
	_ = json.Unmarshal(before, &a)
	_ = json.Unmarshal(after, &b)
	sibling := x.proof(x.a1)
	c.Observations = append(c.Observations, iso.Observation{Name: "stream_after", Detail: string(after)}, iso.Observation{Name: "sibling_counted", Detail: boolText(sibling.Valid())})
	c.Observations = append(c.Observations, iso.Observation{Name: "conntrack_before", Detail: string(ctBefore)}, iso.Observation{Name: "conntrack_after", Detail: string(ctAfter)})
	tracked := ctBeforeErr == nil && strings.Contains(string(ctBefore), "tcp ") && strings.Contains(string(ctBefore), "udp ") && strings.Contains(string(ctBefore), "dport=8080 ")
	cleared := ctAfterErr == nil && !strings.Contains(string(ctAfter), "dport=8080 ")
	c.Status = iso.NegativeStatus(c.Positive, e == nil && err == nil && resp.Status == 202 && applied && a.TCP > 0 && a.UDP > 0 && sibling.Valid() && tracked, b.TCPFail != "" && b.UDPFail != "" && cleared)
	c.Actual = "binding removed and new serving generation=" + boolText(applied) + "; sibling counted=" + boolText(sibling.Valid()) + "; native route withdrawal and kernel revoke are not independently attributed"
	if !applied {
		c.Status = iso.StatusBlocked
		c.Actual = "post-revoke serving apply missing; agent owns exact observation below"
	}
	x.observation(&c, r)
	x.add("AT13", c)
	if !applied || source == "" {
		x.add("AT13", iso.Check{Name: "post-revoke kernel ingress attribution", Status: iso.StatusBlocked, Positive: c.Positive, Actual: "revoke did not reach a new serving generation with a known overlay source; ObserveMemberIngress was not called", Owner: "w2-agent-core"})
		return
	}
	x.postRevokeIngress(source, r.usageDevice, x.a1)
}

// D-102: retain process identity before the original stop. Receipt reads use
// docker cp even for a running clone source, so this also works while stopped.
func (x *isolationRun) agentStopIdentity(container string) map[string]any {
	row := map[string]any{"available": false, "captured_at": time.Now().UTC()}
	raw, err := x.r.lab.docker(container, "sh", "-ec", `cat /var/lib/vpn-node/e2e/agent-process-id; cat /var/lib/vpn-node/e2e/agent.pid; cat /proc/$(cat /var/lib/vpn-node/e2e/agent.pid)/stat`)
	lines := strings.Split(strings.TrimSpace(string(raw)), "\n")
	if err != nil || len(lines) != 3 {
		return row
	}
	launch := strings.TrimSpace(lines[0])
	if _, err := uuid.Parse(launch); err != nil {
		return row
	}
	pid, err := strconv.Atoi(strings.TrimSpace(lines[1]))
	fields := strings.Fields(lines[2][strings.LastIndex(lines[2], ")")+1:])
	if err != nil || pid <= 1 || len(fields) < 20 {
		return row
	}
	row["available"], row["launch_id"], row["pid"], row["start_ticks"] = true, launch, pid, fields[19]
	return row
}

func (x *isolationRun) agentStopReceipt(container string, identity map[string]any) map[string]any {
	row := map[string]any{"identity_before_stop": identity, "parent_wait_available": false,
		"scope": "Actual agent exit from matching parent wait receipt; container exit is shutdown-handler completion only; sigkill sidecar is an attempted escalation"}
	if state, err := exec.Command("docker", "inspect", "--format={{json .State}}", container).Output(); err == nil && json.Valid(state) {
		row["container_state_at_read"] = json.RawMessage(state)
	}
	if identity["available"] != true {
		return row
	}
	launch := identity["launch_id"].(string)
	for _, suffix := range []string{".json", ".sigkill.json"} {
		path := filepath.Join(x.t.TempDir(), "receipt"+suffix)
		err := exec.Command("docker", "cp", container+":/var/lib/vpn-node/e2e/agent-exits/"+launch+suffix, path).Run()
		if err != nil {
			continue
		}
		raw, err := os.ReadFile(path)
		if err != nil || !json.Valid(raw) {
			continue
		}
		if suffix == ".sigkill.json" {
			row["attempted_escalation"] = json.RawMessage(raw)
			continue
		}
		var receipt struct {
			ID         string `json:"id"`
			PID        int    `json:"pid"`
			StartTicks string `json:"start_ticks"`
			ExitCode   *int   `json:"exit_code"`
			Signal     *int   `json:"signal"`
		}
		if json.Unmarshal(raw, &receipt) != nil {
			continue
		}
		matched := receipt.ID == launch && receipt.PID == identity["pid"] && receipt.StartTicks == identity["start_ticks"]
		row["parent_wait_receipt"], row["parent_wait_available"], row["parent_identity_matched"] = json.RawMessage(raw), true, matched
		row["cooperative_exit"] = matched && receipt.Signal == nil && receipt.ExitCode != nil && *receipt.ExitCode == 0
	}
	return row
}

func (x *isolationRun) restart() {
	c := iso.Check{Name: "node restart with durable identity", Positive: x.proof(x.a1), Owner: "w2-agent-core / w3-devstack-e2e"}
	before, _ := x.r.lab.docker(x.r.lab.node, "cat", "/run/vpn-node/heartbeat")
	boot := regexp.MustCompile(`(?m)^boot_id (\S+)$`).FindStringSubmatch(string(before))
	x.retainReasonLogs("before-restart")
	leaseBefore, beforeOK := x.readNodeLease()
	agentIdentity := x.agentStopIdentity(x.r.lab.node)
	start := time.Now()
	out, e := exec.Command("docker", "stop", "--time", "25", x.r.lab.node).CombinedOutput()
	stopped := time.Now()
	agentStop := x.agentStopReceipt(x.r.lab.node, agentIdentity)
	leaseStopped, stoppedOK := x.readNodeLease()
	startRequested := time.Now()
	startOut, startErr := exec.Command("docker", "start", x.r.lab.node).CombinedOutput()
	started := time.Now()
	x.extra("restart-lifecycle.json", map[string]any{
		"run_id": x.records["AT13"].RunID, "stop_started": start.UTC(), "stop_completed": stopped.UTC(),
		"start_requested": startRequested.UTC(), "start_completed": started.UTC(),
		"stop_duration_ns":             strconv.FormatInt(stopped.Sub(start).Nanoseconds(), 10),
		"stopped_snapshot_duration_ns": strconv.FormatInt(startRequested.Sub(stopped).Nanoseconds(), 10),
		"restart_duration_ns":          strconv.FormatInt(started.Sub(start).Nanoseconds(), 10),
		"stop_ok":                      e == nil, "start_ok": startErr == nil,
		"agent_stop": agentStop, "agent_budget_seconds": 15, "container_grace_seconds": 25,
		"before": leaseBefore, "stopped": leaseStopped, "before_available": beforeOK, "stopped_available": stoppedOK,
		"stored_lease_survived_stop": beforeOK && stoppedOK && leaseBefore.LeaseID == leaseStopped.LeaseID && leaseBefore.MonoSent == leaseStopped.MonoSent,
		"scope":                      "Docker stop/start command brackets; stopped SQLite snapshot adds measured downtime. Same boot, not OS reboot or exact SIGTERM/exit timestamps.",
	})
	if startErr != nil {
		e = startErr
	}
	out = append(out, startOut...)
	_ = exec.Command("docker", "exec", "-d", x.r.lab.node, "/tmp/isolation-probe", "nft-clock").Run()
	wait, cancel := context.WithTimeout(x.ctx, 90*time.Second)
	ready := waitUntil(wait, 2*time.Second, func() bool {
		raw, _ := x.r.lab.docker(x.r.lab.node, "cat", "/run/vpn-node/heartbeat")
		// A container process restart retains the kernel boot ID. Require a
		// fresh heartbeat as well as serving read-back; this is not OS reboot evidence.
		return len(boot) == 2 && strings.Contains(string(raw), "boot_id "+boot[1]) && !bytes.Equal(raw, before) && strings.Contains(string(raw), "\nserving 1\n") && x.r.lab.forwardChain().MemberAccept > 0
	})
	cancel()
	after := x.proof(x.a1)
	for attempt, deadline := 0, time.Now().Add(60*time.Second); !after.Valid() && time.Now().Before(deadline); attempt++ {
		raw, _ := json.Marshal(after)
		c.Observations = append(c.Observations, iso.Observation{Name: "recovery_attempt_" + strconv.Itoa(attempt), Detail: string(raw)})
		time.Sleep(3 * time.Second)
		after = x.proof(x.a1)
	}
	afterRaw, _ := json.Marshal(after)
	c.Observations = append(c.Observations, iso.Observation{Name: "recovered_control", Detail: string(afterRaw)})
	c.Status = iso.NegativeStatus(c.Positive, e == nil && ready && after.Valid(), true)
	c.Actual = "container restart=" + strings.TrimSpace(string(out)) + "; recovered counted=" + boolText(after.Valid()) + "; continuous forbidden-flow coverage not established"
	clockRaw, clockErr := x.r.lab.docker(x.r.lab.node, "/tmp/isolation-probe", "producer-clock")
	if clockErr != nil || !json.Valid(clockRaw) {
		x.t.Error("post-restart producer clock unavailable")
	} else {
		x.extra("producer-clock-after-restart.json", json.RawMessage(clockRaw))
	}
	x.observation(&c, x.a1)
	x.add("AT13", c)
	x.add("AT13", iso.Check{Name: "continuous crash/NetBird/reboot/updater transitions", Status: iso.StatusBlocked, Positive: after, Actual: "restart recovery measured; full continuous fault matrix remains unproved", Owner: "acceptance / operator"})
}

func (x *isolationRun) deadline() {
	defer x.wholeNodeExpiry()
	x.admin, _ = x.r.lab.login(x.ctx, "e2e-admin", "admin")
	if x.admin == nil {
		return
	}
	// F21-01: choose the finite grant's deadline from a fresh accepted renewal.
	// This is read-only observation before creating the grant, never an edit of
	// an existing grant or lease. Missing/late anchors block with their samples.
	anchorConn, anchorErr := x.r.lab.db(x.ctx)
	if anchorErr != nil {
		x.add("AT13", iso.Check{Name: "lease member expiry", Status: iso.StatusBlocked, Actual: "finite-member-schedule.json: anchor database unavailable", Owner: "acceptance"})
		x.extra("finite-member-schedule.json", map[string]any{"run_id": x.records["AT13"].RunID, "error": "anchor database unavailable"})
		return
	}
	anchorWait, anchorCancel := context.WithTimeout(x.ctx, 60*time.Second)
	var schedule iso.MemberExpirySchedule
	anchorSamples := []map[string]any{}
	anchored := waitUntil(anchorWait, time.Second, func() bool {
		var issued, expires time.Time
		var accepted bool
		err := anchorConn.QueryRow(anchorWait, `SELECT issued_at,expires_at,
            EXISTS(SELECT 1 FROM node_observations o WHERE o.node_id=s.node_id AND o.report_payload->'lease'->>'lease_id'=s.id::text AND o.report_payload->>'member_forwarding_enabled'='true')
            FROM serving_leases s WHERE node_id=$1 ORDER BY issued_at DESC LIMIT 1`, x.r.nodeID).Scan(&issued, &expires, &accepted)
		var ok bool
		schedule, ok = iso.PlanMemberExpiry(issued, expires, time.Now().UTC(), accepted)
		anchorSamples = append(anchorSamples, map[string]any{"schedule": schedule, "accepted_serving": accepted, "read_ok": err == nil})
		return err == nil && ok
	})
	anchorCancel()
	anchorConn.Close(x.ctx)
	x.extra("finite-member-schedule.json", map[string]any{"run_id": x.records["AT13"].RunID, "anchored": anchored, "schedule": schedule, "samples": anchorSamples})
	if !anchored {
		x.add("AT13", iso.Check{Name: "lease member expiry", Status: iso.StatusBlocked, Actual: "finite-member-schedule.json: no fresh accepted 60-second renewal anchor", Owner: "acceptance"})
		return
	}
	end := schedule.Deadline
	r := x.join("iso-expiry", x.r.planRevID, "expiry", end)
	if r == nil {
		x.add("AT13", iso.Check{Name: "lease member expiry", Status: iso.StatusBlocked, Actual: "finite member admission failed", Owner: "w3-wire-members"})
		return
	}
	if !x.install(r.lab.member) {
		return
	}
	c := iso.Check{Name: "lease member expiry under control loss", Positive: x.proof(r), Owner: "w2-agent-core"}
	conn, e := r.lab.db(x.ctx)
	if e != nil {
		return
	}
	defer conn.Close(x.ctx)
	var lease []byte
	binding, bound := readProjectedBinding(r.desiredRaw(), r.usageDevice)
	var bounds struct {
		Expires time.Time `json:"expires_at"`
		Members []struct {
			Member     uuid.UUID `json:"member_id"`
			End        time.Time `json:"lease_end"`
			ServiceEnd time.Time `json:"effective_service_end"`
		} `json:"members"`
	}
	// With a fixed 60-second node window, an early lease correctly expires
	// before this finite grant. Wait for ordinary renewal to reach the member
	// deadline while the node lease still extends beyond it. Never edit either.
	wait, cancel := context.WithDeadline(x.ctx, end.Add(-5*time.Second))
	samples := []map[string]any{}
	leaseBound := waitUntil(wait, time.Second, func() bool {
		e = conn.QueryRow(wait, `SELECT jsonb_build_object('lease_id',id,'issued_at',issued_at,'expires_at',expires_at,'generation',policy_generation::text,'members',envelope->'signed'->'members',
            'accepted_serving',EXISTS(SELECT 1 FROM node_observations o WHERE o.node_id=s.node_id AND o.report_payload->'lease'->>'lease_id'=s.id::text AND o.report_payload->>'member_forwarding_enabled'='true'))
            FROM serving_leases s WHERE node_id=$1 ORDER BY issued_at DESC LIMIT 1`, r.nodeID).Scan(&lease)
		if e != nil || json.Unmarshal(lease, &bounds) != nil {
			return false
		}
		samples = append(samples, map[string]any{"at": time.Now().UTC(), "lease": json.RawMessage(append([]byte(nil), lease...))})
		var receipt struct {
			Accepted bool `json:"accepted_serving"`
		}
		if json.Unmarshal(lease, &receipt) != nil || !receipt.Accepted || !bound || !bounds.Expires.After(end.Add(25*time.Second)) {
			return false
		}
		for _, m := range bounds.Members {
			if m.Member == binding.Member && m.ServiceEnd.Equal(end) && m.End.Equal(end) {
				return true
			}
		}
		return false
	})
	cancel()
	x.extra("finite-member-renewal-wait.json", map[string]any{"run_id": x.records["AT13"].RunID, "member_deadline": end, "samples": samples, "qualified": leaseBound})
	c.Observations = append(c.Observations, iso.Observation{Name: "signed_lease_bounds", Detail: string(lease)}, iso.Observation{Name: "grant_deadline", Detail: end.Format(time.RFC3339)})
	if !c.Positive.Valid() || e != nil || !leaseBound || !time.Now().Before(end.Add(-5*time.Second)) {
		c.Status = iso.StatusBlocked
		c.Actual = "counted finite flow, matching signed member deadline, or pre-expiry fault window unavailable"
		x.add("AT13", c)
		return
	}
	for time.Until(end) > 5*time.Second {
		select {
		case <-x.ctx.Done():
			return
		case <-time.After(time.Second):
		}
	}
	e = exec.Command("docker", "stop", "--time", "2", r.lab.control, r.lab.prefix+"-worker").Run()
	c.Observations = append(c.Observations, iso.Observation{Name: "control_stopped_at", Detail: time.Now().UTC().Format(time.RFC3339)})
	defer func() {
		x.lastControlStart = time.Now().UTC()
		_ = exec.Command("docker", "start", r.lab.control, r.lab.prefix+"-worker").Run()
		_ = x.waitControl()
	}()
	if e != nil || !time.Now().Before(end) {
		c.Status = iso.StatusBlocked
		c.Actual = "control stop did not complete before the finite member deadline"
		x.add("AT13", c)
		return
	}
	for time.Now().Before(end.Add(2 * time.Second)) {
		select {
		case <-x.ctx.Done():
			return
		case <-time.After(time.Second):
		}
	}
	frozen, available := r.admissionBytes()
	denied := true
	routed, probesOK := true, true
	servingReads := []iso.MemberExpiryServingRead{}
	readServing := func() {
		read := iso.MemberExpiryServingRead{At: time.Now().UTC()}
		heartbeat, hbErr := r.lab.docker(r.lab.node, "cat", "/run/vpn-node/heartbeat")
		chain, chainErr := r.lab.docker(r.lab.node, "nft", "list", "chain", "inet", "fvpn", "forward")
		read.End = time.Now().UTC()
		read.Heartbeat, read.ForwardChain = string(heartbeat), string(chain)
		if hbErr != nil || chainErr != nil {
			read.ReadError = fmt.Sprintf("heartbeat=%v; forward_chain=%v", hbErr, chainErr)
		}
		servingReads = append(servingReads, read)
	}
	readServing()
	for i := 0; i < 5; i++ {
		route, result, ingress, delivered := x.capturedConnect(r, r.lab.prefix+"-origin", r.originIP(), 443, &c)
		c.Observations = append(c.Observations, iso.Observation{Name: "post_deadline_" + strconv.Itoa(i), Detail: "result=" + result + "; route=" + route})
		denied = denied && result == "timeout" && !delivered
		routed = routed && strings.Contains(route, "dev fvnb0")
		probesOK = probesOK && result != "probe_error" && ingress
		readServing()
		time.Sleep(time.Second)
	}
	after, ok := r.admissionBytes()
	c.Observations = append(c.Observations, iso.Observation{Name: "post_deadline_bytes_before", Detail: fmt.Sprint(frozen)}, iso.Observation{Name: "post_deadline_bytes_after", Detail: fmt.Sprint(after)})
	// All five member-denial probes must finish while the original node lease
	// is still valid, so whole-node expiry cannot supply this result.
	nodeStillValid := time.Now().Before(bounds.Expires)
	c.Observations = append(c.Observations, iso.Observation{Name: "node_lease_valid_through_last_probe", Detail: boolText(nodeStillValid) + "; completed=" + time.Now().UTC().Format(time.RFC3339Nano) + "; node_expires=" + bounds.Expires.UTC().Format(time.RFC3339Nano)})
	c.Status = iso.NegativeStatus(c.Positive, available && ok && probesOK && nodeStillValid, denied && after == frozen)
	c.Actual = "five new TCP requests after finite signed member deadline; control and worker stopped; admission bytes frozen=" + boolText(after == frozen) + "; route retained throughout=" + boolText(routed) + "; node lease has a later deadline"
	// Read the node locally in the same probe window; a valid lease alone is
	// insufficient when a safety baseline has withdrawn the whole node (r28 M-1).
	servingRaw, _ := json.Marshal(servingReads)
	c.Observations = append(c.Observations, iso.Observation{Name: "member_expiry_serving_reads", Detail: string(servingRaw)})
	var servingEvidence string
	c.Status, servingEvidence = iso.MemberExpiryStatus(c.Status, servingReads)
	c.Actual += "; " + servingEvidence
	x.observation(&c, r)
	x.add("AT13", c)
	if !routed {
		x.add("AT13", iso.Check{Name: "expiry per-packet ingress attribution", Status: iso.StatusBlocked, Positive: c.Positive, Actual: "Native route was withdrawn during the post-deadline window. End-to-end withdrawal was measured; persistent post-expiry ingress was not.", Owner: "w3-devstack-e2e: retain controlled ingress after authorization withdrawal"})
	}
}

const forgedMemberSource = "100.64.7.7"

type leaseSnap struct {
	LeaseID      string          `json:"lease_id,omitempty"`
	Issued       time.Time       `json:"issued_at"`
	Expires      time.Time       `json:"expires_at"`
	Generation   string          `json:"generation"`
	Max          int             `json:"max_offline_seconds"`
	Members      int             `json:"member_count"`
	Source       string          `json:"source"`
	MonoSent     int64           `json:"mono_sent_ns,string"`
	DeadlineMono int64           `json:"deadline_mono_ns,string"`
	Anchor       json.RawMessage `json:"anchor,omitempty"`
}

func (x *isolationRun) wholeNodeExpiry() {
	if x == nil || x.r == nil || x.a1 == nil {
		return
	}
	c := iso.Check{Name: "short whole-node lease expiry", Status: iso.StatusBlocked, Owner: "w2-agent-core", Actual: "not measured"}
	var stopped bool
	defer func() {
		if stopped {
			x.lastControlStart = time.Now().UTC()
			_ = exec.Command("docker", "start", x.r.lab.control, x.r.lab.prefix+"-worker").Run()
		}
		if (stopped || !iso.ControlObservationReady(x.dir, x.records["AT13"].RunID, x.lastControlStart, nil)) && !x.waitControl() {
			c.Status = iso.StatusBlocked
			c.Actual += "; control restart incomplete"
		}
		if !x.fleetAudits(&c, x.fleetRequestID) {
			c.Status = iso.StatusBlocked
			c.Actual += "; pre-enrollment fleet audit missing"
		}
		x.add("AT13", c)
	}()
	if !iso.ControlObservationReady(x.dir, x.records["AT13"].RunID, x.lastControlStart, x.waitControl) {
		c.Actual = "control restoration readiness unavailable before short lease"
		c.Owner = "w3-devstack-e2e"
		return
	}
	admin, err := x.r.lab.login(x.ctx, "e2e-admin", "admin")
	if err != nil {
		c.Actual = "admin login failed before fleet-config write"
		c.Owner = "w3-devstack-e2e"
		return
	}
	x.admin = admin
	route, _ := x.a1.lab.docker(x.a1.lab.member, "ip", "route", "get", x.a1.originIP())
	if !strings.Contains(string(route), "dev fvnb0") {
		selected := x.a1.selectExit(x.ctx, func(k, v string) {
			c.Observations = append(c.Observations, iso.Observation{Name: "pre_lease_" + k, Detail: clipText(v, 400)})
		})
		route, _ = x.a1.lab.docker(x.a1.lab.member, "ip", "route", "get", x.a1.originIP())
		if !selected || !strings.Contains(string(route), "dev fvnb0") {
			c.Actual = "member route via fvnb0 unavailable before the short lease"
			c.Owner = "w3-devstack-e2e"
			return
		}
	}
	c.Observations = append(c.Observations, iso.Observation{Name: "fixed_offline_window", Detail: "60 seconds configured before enrollment; unchanged for this entire run"})
	putAt := time.Now().UTC().Add(-2 * time.Second)
	nodePath := x.r.lab.public + "/api/v1/admin/nodes/" + x.r.nodeID.String()
	get, getErr := x.admin.call(x.ctx, "GET", nodePath, nil, nil)
	capacity := map[string]any{"capacity": map[string]any{"down_bps": 204000000, "up_bps": 200000000, "member_down_bps_cap": 100000000, "member_up_bps_cap": 100000000}}
	write := x.admin.writeNode(x.ctx, "PATCH", nodePath, nodePath, capacity, get.Header.Get("ETag"), nodeFieldsMatch(capacity), []int{200, 202}, isolationCheckNote(&c))
	patch, patchErr := write.Reply, write.Err
	c.Observations = append(c.Observations, iso.Observation{Name: "renewal_capacity_patch", Detail: httpDetail(patch, patchErr) + " get=" + httpDetail(get, getErr)})
	wait, cancel := context.WithTimeout(x.ctx, 90*time.Second)
	var held leaseSnap
	found := waitUntil(wait, time.Second, func() bool {
		snap, ok := x.centralLeaseAfter(putAt)
		if !ok || snap.Max != 60 || snap.Members < 1 {
			return false
		}
		chain := x.r.lab.forwardChain()
		gen, _ := strconv.Atoi(snap.Generation)
		if chain.MemberAccept > 0 && !chain.Baseline && chain.Generation == gen && gen > 0 {
			held = snap
			return true
		}
		return false
	})
	cancel()
	if !found {
		c.Actual = "no applied 60s lease with member grants after the capacity renewal"
		c.Owner = "w2-agent-core / w3-wire-nodes"
		return
	}
	// Retain a continuous two-renewal window before the control-loss deadline.
	renewalCap := x.continuousCapture(x.r.lab.node, "any", "host "+x.a1.originIP()+" and udp port 8080", "renewal-node-capture.txt", 75)
	_ = exec.Command("docker", "exec", "-d", x.r.lab.node, "/tmp/isolation-probe", "packet-clock", "74", "/tmp/isolation-renewal-packets.jsonl").Run()
	_ = exec.Command("docker", "exec", "-d", x.a1.lab.member, "/tmp/isolation-probe", "renewal-probes", x.a1.originIP(), "1", "/tmp/isolation-renewal-probes.jsonl").Run()
	x.sleep(71 * time.Second)
	x.finishCapture(renewalCap)
	for _, item := range []struct{ container, path, name string }{{x.r.lab.node, "/tmp/isolation-renewal-packets.jsonl", "renewal-packets.json"}, {x.a1.lab.member, "/tmp/isolation-renewal-probes.jsonl", "renewal-probes.json"}} {
		raw, _ := exec.Command("docker", "exec", item.container, "cat", item.path).Output()
		rows := []json.RawMessage{}
		for _, line := range bytes.Split(raw, []byte("\n")) {
			if json.Valid(line) {
				rows = append(rows, append(json.RawMessage(nil), line...))
			}
		}
		x.extra(item.name, rows)
	}
	if err = exec.Command("docker", "stop", "--time", "2", x.r.lab.control, x.r.lab.prefix+"-worker").Run(); err != nil {
		c.Actual = "control and worker stop failed"
		c.Owner = "acceptance"
		return
	}
	stopped = true
	c.Observations = append(c.Observations, iso.Observation{Name: "control_stopped_at", Detail: time.Now().UTC().Format(time.RFC3339)})
	if nodeHeld, ok := x.readNodeLease(); ok {
		nodeHeld.Source = "node-store"
		held = nodeHeld
		c.Observations = append(c.Observations, iso.Observation{Name: "node_lease", Detail: mustJSON(held)})
	} else {
		held.Source = "central"
		c.Observations = append(c.Observations, iso.Observation{Name: "node_lease", Detail: "node store unread; using the applied central lease " + mustJSON(held)})
	}
	if held.Max != 60 || held.Members < 1 || held.Issued.Before(putAt) {
		c.Actual = "node does not hold a post-change 60s lease with member grants: " + mustJSON(held)
		c.Owner = "w2-agent-core / w3-wire-nodes"
		return
	}
	if time.Until(held.Expires) < 12*time.Second {
		c.Actual = "signed 60s deadline is inside 12s; measurement window missed: " + mustJSON(held)
		c.Owner = "w2-agent-core"
		return
	}
	earlyOK, before, after, earlyDetail := x.countedForward(x.a1)
	c.Observations = append(c.Observations, iso.Observation{Name: "forward_after_control_loss", Detail: earlyDetail})
	c.Positive = iso.Positive{DeviceID: x.a1.usageDevice.String(), Container: x.a1.lab.member, At: time.Now().UTC().Format(time.RFC3339), Counted: earlyOK, Before: strconv.FormatUint(before, 10), After: strconv.FormatUint(after, 10)}
	if !c.Positive.Valid() {
		c.Actual = "counted forward under the held 60s lease did not increase admission bytes; " + earlyDetail
		c.Owner = "w2-agent-core"
		return
	}
	if !x.sleep(time.Until(held.Expires.Add(-10 * time.Second))) {
		return
	}
	stopCapture := x.startContinuousExpiry(held)
	if !x.sleep(time.Until(held.Expires.Add(-4 * time.Second))) {
		return
	}
	nearOK, _, _, nearDetail := x.countedForward(x.a1)
	c.Observations = append(c.Observations, iso.Observation{Name: "forward_near_deadline", Detail: nearDetail}, iso.Observation{Name: "signed_deadline", Detail: held.Expires.Format(time.RFC3339Nano)})
	tick := x.agentTick()
	c.Observations = append(c.Observations, iso.Observation{Name: "agent_tick", Detail: tick.String()})
	var earlyBaseline, saw time.Time
	var reads []map[string]any
	for {
		now := time.Now()
		chain := x.r.lab.forwardChain()
		readEnd := time.Now()
		beat, _ := x.r.lab.docker(x.r.lab.node, "cat", "/run/vpn-node/heartbeat")
		reads = append(reads, map[string]any{"read_start": now.UTC().Format(time.RFC3339Nano), "read_end": readEnd.UTC().Format(time.RFC3339Nano), "heartbeat_read_end": time.Now().UTC().Format(time.RFC3339Nano), "chain": chain, "heartbeat": strings.TrimSpace(string(beat))})
		baselined := chain.Present && chain.Baseline && chain.Generation == 0 && chain.MemberAccept == 0 && chain.Policy == "drop"
		if baselined && now.Before(held.Expires) && earlyBaseline.IsZero() {
			earlyBaseline = now
		}
		if baselined && !now.Before(held.Expires) && saw.IsZero() {
			saw = now
			break
		}
		if !now.Before(held.Expires.Add(tick)) {
			break
		}
		if !x.sleep(200 * time.Millisecond) {
			return
		}
	}
	heartbeat, _ := x.r.lab.docker(x.r.lab.node, "cat", "/run/vpn-node/heartbeat")
	c.Observations = append(c.Observations, iso.Observation{Name: "baseline_at", Detail: saw.UTC().Format(time.RFC3339Nano)}, iso.Observation{Name: "early_baseline_at", Detail: earlyBaseline.UTC().Format(time.RFC3339Nano)}, iso.Observation{Name: "heartbeat_after_deadline", Detail: strings.TrimSpace(string(heartbeat))})
	x.extra("whole-node-bracketed-reads.json", map[string]any{"signed_deadline": held.Expires, "reads": reads})
	frozen, ok1 := x.a1.admissionBytes()
	dropRoute, dropResult, ingress, delivered := x.capturedConnect(x.a1, x.a1.lab.prefix+"-origin", x.a1.originIP(), 443, &c)
	frozenAfter, ok2 := x.a1.admissionBytes()
	flat := ok1 && ok2 && frozenAfter == frozen
	verdict := stopCapture()
	x.extra("deadline-verdict.json", verdict)
	onTime := verdict.Passed
	drop := dropResult == "timeout" && ingress && !delivered && strings.Contains(dropRoute, "dev fvnb0") && flat
	c.Observations = append(c.Observations, iso.Observation{Name: "post_deadline_forward", Detail: "result=" + dropResult + "; route=" + dropRoute + "; flat=" + boolText(flat) + "; bytes=" + fmt.Sprint(frozen) + "->" + fmt.Sprint(frozenAfter)})
	c.Actual = "60s lease held after control loss; near-deadline forward=" + boolText(nearOK) + "; D-104 exact packet deadline verdict=" + boolText(onTime) + "; last offset ns=" + verdict.LastPositiveOffset + "; first drop offset ns=" + verdict.FirstDropOffset + "; ingress without uplink=" + boolText(drop)
	if !nearOK || !onTime || !drop {
		c.Status = iso.StatusFail
		c.Owner = "w2-agent-core"
		return
	}
	c.Status = iso.StatusPass
	c.Owner = ""
}

func (x *isolationRun) putFleet(seconds int, reason string) (int, string, string) {
	if x.admin == nil {
		return 0, "", "no admin session"
	}
	path := x.r.lab.public + "/api/v1/admin/fleet-config"
	get, err := x.admin.call(x.ctx, "GET", path, nil, nil)
	if err != nil || get.Status != 200 {
		return get.Status, "", httpDetail(get, err) + " " + apiErrorText(get.Body)
	}
	put, err := x.admin.call(x.ctx, "PUT", path, map[string]any{"max_offline_lease_seconds": seconds, "reason": reason}, map[string]string{"If-Match": get.Header.Get("ETag"), "Idempotency-Key": uuid.NewString()})
	return put.Status, put.Header.Get("X-Request-ID"), httpDetail(put, err) + " etag=" + put.Header.Get("ETag") + " body=" + clipText(string(put.Body), 500)
}

func (x *isolationRun) waitControl() bool {
	// Same existing 90s restoration budget; readiness now includes accepted
	// current observations and a drained outbox, not just an HTTP health check.
	start := time.Now().UTC()
	x.lastControlStart = start
	wait, cancel := context.WithTimeout(x.ctx, 90*time.Second)
	defer cancel()
	samples := []map[string]any{}
	ready := waitUntil(wait, 2*time.Second, func() bool {
		admin, err := x.r.lab.login(wait, "e2e-admin", "admin")
		if err != nil {
			return false
		}
		x.admin = admin
		resp, err := admin.call(wait, "GET", x.r.lab.public+"/api/v1/admin/fleet-config", nil, nil)
		if err != nil || resp.Status != 200 {
			return false
		}
		row := x.networkSnapshot("control restoration readiness")
		var pending struct {
			Pending int       `json:"pending"`
			At      time.Time `json:"at"`
		}
		raw, e := x.r.lab.docker(x.r.lab.node, "/tmp/isolation-probe", "observation-pending")
		queueOK := e == nil && json.Unmarshal(raw, &pending) == nil && !pending.At.IsZero()
		row["queue_available"], row["queue"] = queueOK, pending
		samples = append(samples, row)
		var report struct {
			Observed   time.Time `json:"observed_at"`
			Applied    string    `json:"applied_config_generation"`
			Forwarding bool      `json:"member_forwarding_enabled"`
		}
		body, _ := row["observation"].(json.RawMessage)
		_, _, _, generation := x.r.desiredMemberView()
		if json.Unmarshal(body, &report) != nil {
			return false
		}
		return iso.SampleControlReadiness(start, generation, iso.ControlReadinessSample{
			LoginOK:                 true,
			FleetConfigStatus:       resp.Status,
			QueueAvailable:          queueOK,
			QueuePending:            pending.Pending,
			ObservedAt:              report.Observed,
			AppliedGeneration:       report.Applied,
			MemberForwardingEnabled: report.Forwarding,
		})
	})
	x.extra("control-observation-readiness.json", map[string]any{"run_id": x.records["AT13"].RunID, "started_at": start, "completed_at": time.Now().UTC(), "ready": ready, "timeout_seconds": 90, "samples": samples})
	return ready
}

func (x *isolationRun) fleetAudits(c *iso.Check, ids ...string) bool {
	ok := true
	for _, id := range ids {
		if id == "" {
			ok = false
			c.Observations = append(c.Observations, iso.Observation{Name: "fleet_audit_missing", Detail: "request id empty"})
			continue
		}
		resp, err := x.admin.call(x.ctx, "GET", x.r.lab.public+"/api/v1/admin/audit-events?request_id="+id+"&limit=5", nil, nil)
		detail := httpDetail(resp, err) + " " + clipText(string(resp.Body), 2000)
		c.Observations = append(c.Observations, iso.Observation{Name: "fleet_audit_" + id, Detail: detail})
		if err != nil || resp.Status != 200 || !strings.Contains(string(resp.Body), "fleet_config.update") {
			ok = false
		}
	}
	return ok
}

func (x *isolationRun) centralLeaseAfter(after time.Time) (leaseSnap, bool) {
	conn, err := x.r.lab.db(x.ctx)
	if err != nil {
		return leaseSnap{}, false
	}
	defer conn.Close(x.ctx)
	var raw []byte
	err = conn.QueryRow(x.ctx, `SELECT jsonb_build_object(
		'issued_at', issued_at,
		'expires_at', expires_at,
		'generation', policy_generation::text,
		'max_offline_seconds', envelope->'signed'->'max_offline_seconds',
		'member_count', jsonb_array_length(COALESCE(envelope->'signed'->'members', '[]'::jsonb)),
		'source', 'central')
		FROM serving_leases WHERE node_id=$1 AND issued_at>$2 ORDER BY issued_at DESC LIMIT 1`, x.r.nodeID, after).Scan(&raw)
	if err != nil {
		return leaseSnap{}, false
	}
	var snap leaseSnap
	if json.Unmarshal(raw, &snap) != nil || snap.Expires.IsZero() {
		return leaseSnap{}, false
	}
	return snap, true
}

func (x *isolationRun) readNodeLease() (leaseSnap, bool) {
	return x.readContainerLease(x.r.lab.node)
}

func (x *isolationRun) readContainerLease(container string) (leaseSnap, bool) {
	dir := x.t.TempDir()
	for _, name := range []string{"agent.db", "agent.db-wal", "agent.db-shm"} {
		_ = exec.Command("docker", "cp", container+":/var/lib/vpn-node/state/"+name, filepath.Join(dir, name)).Run()
	}
	db, err := sql.Open("sqlite", "file:"+filepath.Join(dir, "agent.db")+"?mode=ro")
	if err != nil {
		return leaseSnap{}, false
	}
	defer db.Close()
	var issued, expires, envelope string
	var mono int64
	var anchor []byte
	if db.QueryRow(`SELECT issued_at, expires_at, envelope, mono_sent_ns FROM lease WHERE id = 1`).Scan(&issued, &expires, &envelope, &mono) != nil {
		return leaseSnap{}, false
	}
	var doc struct {
		Signed struct {
			LeaseID    string            `json:"lease_id"`
			Max        int               `json:"max_offline_seconds"`
			Members    []json.RawMessage `json:"members"`
			Generation string            `json:"config_generation"`
		} `json:"signed"`
	}
	if json.Unmarshal([]byte(envelope), &doc) != nil {
		return leaseSnap{}, false
	}
	is, e1 := time.Parse(time.RFC3339Nano, issued)
	ex, e2 := time.Parse(time.RFC3339Nano, expires)
	if e1 != nil || e2 != nil {
		return leaseSnap{}, false
	}
	_ = db.QueryRow(`SELECT json_object('mono_ns',cast(mono_ns as text),'server_unix_ns',cast(server_unix_ns as text),'wall_unix_ns',cast(wall_unix_ns as text),'trusted',trusted) FROM anchor WHERE id=1`).Scan(&anchor)
	return leaseSnap{LeaseID: doc.Signed.LeaseID, MonoSent: mono, DeadlineMono: mono + int64(ex.Sub(is)), Anchor: anchor, Issued: is.UTC(), Expires: ex.UTC(), Generation: doc.Signed.Generation, Max: doc.Signed.Max, Members: len(doc.Signed.Members)}, true
}

func (x *isolationRun) countedForward(r *runner) (bool, uint64, uint64, string) {
	before, ok1 := r.admissionBytes()
	route, _ := r.lab.docker(r.lab.member, "ip", "route", "get", r.originIP())
	ctx, cancel := context.WithTimeout(x.ctx, 8*time.Second)
	defer cancel()
	out, err := exec.CommandContext(ctx, "docker", "exec", r.lab.member, "wget", "--timeout=3", "--tries=1", "--ca-certificate=/etc/vpn-node/ca.pem", "-qO-", r.lab.releases+"/healthz").CombinedOutput()
	after, ok2 := r.admissionBytes()
	ok := ok1 && ok2 && after > before && err == nil && strings.Contains(string(route), "dev fvnb0")
	detail := "route=" + strings.TrimSpace(string(route)) + "; wget_ok=" + boolText(err == nil) + "; bytes=" + fmt.Sprint(before) + "->" + fmt.Sprint(after) + "; body=" + clipText(string(out), 80)
	return ok, before, after, detail
}

func (x *isolationRun) agentTick() time.Duration {
	raw, err := x.r.lab.docker(x.r.lab.node, "cat", "/etc/vpn-node/agent-run.json")
	var cfg struct {
		Heartbeat int `json:"heartbeat_seconds"`
		Poll      int `json:"poll_seconds"`
	}
	if err != nil || json.Unmarshal(raw, &cfg) != nil {
		return 5 * time.Second
	}
	tick := cfg.Heartbeat
	if cfg.Poll > 0 && (tick <= 0 || cfg.Poll < tick) {
		tick = cfg.Poll
	}
	if tick <= 0 {
		tick = 5
	}
	return time.Duration(tick) * time.Second
}

func (x *isolationRun) sleep(d time.Duration) bool {
	if d <= 0 {
		return true
	}
	timer := time.NewTimer(d)
	defer timer.Stop()
	select {
	case <-x.ctx.Done():
		return false
	case <-timer.C:
		return true
	}
}

func (x *isolationRun) spoofedSource() {
	positive := x.proof(x.a1)
	c := iso.Check{Name: "unknown/spoofed member source", Positive: positive, Owner: "w2-agent-core"}
	live := memberIP(x.a1)
	forged := forgedMemberSource
	if forged == live || forged == memberIP(x.a2) || forged == memberIP(x.b1) {
		c.Status = iso.StatusBlocked
		c.Owner = "w3-devstack-e2e"
		c.Actual = "forged source collided with a live overlay address"
		x.add("AT12", c)
		return
	}
	dest := x.a1.originIP()
	denied, derr := x.stack.ObserveMemberIngress(x.ctx, forged, dest)
	admitted, aerr := x.stack.ObserveMemberIngress(x.ctx, live, dest)
	up := "u_" + strings.ReplaceAll(x.a1.usageDevice.String(), "-", "")
	down := "d_" + strings.ReplaceAll(x.a1.usageDevice.String(), "-", "")
	c.Observations = append(c.Observations,
		iso.Observation{Name: "forged_inject", Detail: ingressNote(denied, derr)},
		iso.Observation{Name: "admitted_inject", Detail: ingressNote(admitted, aerr)},
	)
	if derr != nil || aerr != nil {
		c.Status = iso.StatusBlocked
		c.Owner = "w3-devstack-e2e"
		c.Actual = "ObserveMemberIngress failed; forged_err=" + errText(derr) + "; admitted_err=" + errText(aerr)
		x.add("AT12", c)
		return
	}
	deniedOK := ingressDenied(denied)
	admittedOK := ingressAdmitted(admitted, up, down)
	c.Status = iso.NegativeStatus(positive, true, deniedOK && admittedOK)
	if c.Status == iso.StatusPass {
		c.Owner = ""
	}
	c.Actual = "forged " + forged + " ctunku+1 and zero forwarded=" + boolText(deniedOK) + "; admitted " + up + " +1=" + boolText(admittedOK)
	x.add("AT12", c)
}

func (x *isolationRun) postRevokeIngress(revokedSource string, revokedDevice uuid.UUID, sibling *runner) {
	positive := x.proof(sibling)
	c := iso.Check{Name: "post-revoke kernel ingress attribution", Positive: positive, Owner: "w2-agent-core"}
	dest := sibling.originIP()
	revoked, rerr := x.stack.ObserveMemberIngress(x.ctx, revokedSource, dest)
	siblingSource := memberIP(sibling)
	admitted, aerr := x.stack.ObserveMemberIngress(x.ctx, siblingSource, dest)
	revokedUp := "u_" + strings.ReplaceAll(revokedDevice.String(), "-", "")
	up := "u_" + strings.ReplaceAll(sibling.usageDevice.String(), "-", "")
	down := "d_" + strings.ReplaceAll(sibling.usageDevice.String(), "-", "")
	c.Observations = append(c.Observations,
		iso.Observation{Name: "revoked_inject", Detail: ingressNote(revoked, rerr)},
		iso.Observation{Name: "admitted_inject", Detail: ingressNote(admitted, aerr)},
	)
	if rerr != nil || aerr != nil {
		c.Status = iso.StatusBlocked
		c.Owner = "w3-devstack-e2e"
		c.Actual = "ObserveMemberIngress failed after revoke; revoked_err=" + errText(rerr) + "; admitted_err=" + errText(aerr)
		x.add("AT13", c)
		return
	}
	revokedOK := ingressDenied(revoked) && revoked.Before[revokedUp] == revoked.After[revokedUp]
	admittedOK := ingressAdmitted(admitted, up, down)
	c.Status = iso.NegativeStatus(positive, revokedSource != "" && siblingSource != "", revokedOK && admittedOK)
	if c.Status == iso.StatusPass {
		c.Owner = ""
	}
	c.Actual = "revoked " + revokedSource + " ctunku+1 and zero forwarded=" + boolText(revokedOK) + "; sibling " + up + " +1=" + boolText(admittedOK)
	x.add("AT13", c)
}

func ingressHook(p MemberIngressProof) bool {
	return p.Mechanism == "tun-mirred" && p.LinkType == 65534 && p.MemberIface == "fvmb0" && p.SourcePort == 40000 && p.DestPort == 9
}

func ingressDenied(p MemberIngressProof) bool {
	if !ingressHook(p) || !captureEmpty(p.UplinkCapture) || !captureEmpty(p.OriginCapture) {
		return false
	}
	ct, ok := ingressCounterDelta(p.Before, p.After, "ctunku")
	return ok && ct.Packets == 1 && ct.Bytes > 0 && deviceCountersHeld(p.Before, p.After)
}

func ingressAdmitted(p MemberIngressProof, up, down string) bool {
	if !ingressHook(p) || up == "" || !captureSawDatagram(p.UplinkCapture) || !captureSawDatagram(p.OriginCapture) {
		return false
	}
	got, ok := ingressCounterDelta(p.Before, p.After, up)
	ct, ctOK := ingressCounterDelta(p.Before, p.After, "ctunku")
	return ok && got.Packets == 1 && got.Bytes > 0 && ctOK && ct.Packets == 0 && deviceCountersHeld(p.Before, p.After, up, down)
}

func ingressNote(p MemberIngressProof, err error) string {
	ct, _ := ingressCounterDelta(p.Before, p.After, "ctunku")
	raw, _ := json.Marshal(map[string]any{
		"error": errText(err), "mechanism": p.Mechanism, "link_type": p.LinkType, "member_iface": p.MemberIface,
		"source": p.Source, "dest": p.Dest, "source_port": p.SourcePort, "dest_port": p.DestPort,
		"ctunku_packets": ct.Packets, "ctunku_bytes": ct.Bytes, "deltas": p.Deltas,
		"uplink_capture": clipText(p.UplinkCapture, 800), "origin_capture": clipText(p.OriginCapture, 800),
	})
	return string(raw)
}

func errText(err error) string {
	if err == nil {
		return ""
	}
	return clipText(err.Error(), 300)
}

func (x *isolationRun) startConvergence() {
	if x.stopConv != nil || x.r == nil {
		return
	}
	x.stopConv = make(chan struct{})
	x.convStopped = make(chan struct{})
	go x.sampleLoop()
}

func (x *isolationRun) signalConv() {
	x.convOnce.Do(func() {
		if x.stopConv != nil {
			close(x.stopConv)
		}
	})
}

func (x *isolationRun) stopConvergence() {
	if x.stopConv == nil {
		return
	}
	x.signalConv()
	select {
	case <-x.convStopped:
	case <-time.After(15 * time.Second):
	}
}

func (x *isolationRun) sampleLoop() {
	defer close(x.convStopped)
	x.takeSample()
	tick := time.NewTicker(250 * time.Millisecond)
	defer tick.Stop()
	for {
		select {
		case <-x.ctx.Done():
			return
		case <-x.stopConv:
			x.takeSample()
			return
		case <-tick.C:
			x.takeSample()
		}
	}
}

func (x *isolationRun) noteFirstCounted(p iso.Positive) {
	x.convMu.Lock()
	if x.firstCounted != "" {
		x.convMu.Unlock()
		return
	}
	x.firstCounted = "at=" + p.At + " device=" + p.DeviceID + " bytes=" + p.Before + "->" + p.After
	x.convMu.Unlock()
	x.signalConv()
	x.noteRulesetReadback()
}

func (x *isolationRun) takeSample() {
	if x.r == nil || x.r.nodeID == uuid.Nil {
		return
	}
	row := map[string]any{"at": time.Now().UTC().Format(time.RFC3339Nano)}
	conn, err := x.r.lab.db(x.ctx)
	if err != nil {
		row["db"] = "unavailable"
	} else {
		var raw []byte
		qerr := conn.QueryRow(x.ctx, `SELECT jsonb_build_object(
			'desired_generation', n.desired_config_generation::text,
			'applied_generation', n.applied_config_generation::text,
			'provisioning_state', n.provisioning_state,
			'safety_status', n.safety_status,
			'publication_intent', e.publication_intent,
			'publication_observed', e.publication_observed,
			'desired_bindings', (SELECT jsonb_array_length(COALESCE(d.envelope->'signed'->'device_bindings','[]'::jsonb)) FROM desired_state_envelopes d WHERE d.node_id=n.id),
			'lease_id', (SELECT s.id::text FROM serving_leases s WHERE s.node_id=n.id ORDER BY s.issued_at DESC LIMIT 1),
			'lease_issued_at', (SELECT to_char(s.issued_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') FROM serving_leases s WHERE s.node_id=n.id ORDER BY s.issued_at DESC LIMIT 1),
			'lease_generation', (SELECT s.policy_generation::text FROM serving_leases s WHERE s.node_id=n.id ORDER BY s.issued_at DESC LIMIT 1),
			'lease_members', (SELECT jsonb_array_length(COALESCE(s.envelope->'signed'->'members','[]'::jsonb)) FROM serving_leases s WHERE s.node_id=n.id ORDER BY s.issued_at DESC LIMIT 1),
			'lease_max_offline_seconds', (SELECT s.envelope->'signed'->'max_offline_seconds' FROM serving_leases s WHERE s.node_id=n.id ORDER BY s.issued_at DESC LIMIT 1),
			'block_reasons', (SELECT o.report_payload->'forwarding_block_reasons' FROM node_observations o WHERE o.node_id=n.id ORDER BY o.received_at DESC LIMIT 1),
			'forwarding', (SELECT o.report_payload->'member_forwarding_enabled' FROM node_observations o WHERE o.node_id=n.id ORDER BY o.received_at DESC LIMIT 1),
			'observation_generation', (SELECT o.report_payload->'applied_config_generation' FROM node_observations o WHERE o.node_id=n.id ORDER BY o.received_at DESC LIMIT 1),
			'observation_id', (SELECT o.id::text FROM node_observations o WHERE o.node_id=n.id ORDER BY o.received_at DESC LIMIT 1),
			'observation_at', (SELECT o.report_payload->>'observed_at' FROM node_observations o WHERE o.node_id=n.id ORDER BY o.received_at DESC LIMIT 1),
			'observed_lease_id', (SELECT o.report_payload->'lease'->>'lease_id' FROM node_observations o WHERE o.node_id=n.id ORDER BY o.received_at DESC LIMIT 1),
			'errors', (SELECT o.report_payload->'errors' FROM node_observations o WHERE o.node_id=n.id ORDER BY o.received_at DESC LIMIT 1),
			'checks', (SELECT o.report_payload->'checks' FROM node_observations o WHERE o.node_id=n.id ORDER BY o.received_at DESC LIMIT 1)
		) FROM nodes n LEFT JOIN exits e ON e.node_id=n.id WHERE n.id=$1`, x.r.nodeID).Scan(&raw)
		_ = conn.Close(x.ctx)
		if qerr != nil {
			row["db_error"] = clipText(qerr.Error(), 300)
		} else if json.Unmarshal(raw, &row) != nil {
			row["db_error"] = "sample decode failed"
		} else {
			row["at"] = time.Now().UTC().Format(time.RFC3339Nano)
			row["lease_check"] = leaseCheckOnly(row["checks"])
		}
	}
	chain := x.r.lab.forwardChain()
	row["forward_generation"] = strconv.Itoa(chain.Generation)
	row["forward_chain_at"] = time.Now().UTC().Format(time.RFC3339Nano)
	row["forward_present"] = chain.Present
	row["forward_baseline"] = chain.Baseline
	row["forward_member_accept"] = chain.MemberAccept
	x.convMu.Lock()
	defer x.convMu.Unlock()
	// Preserve repeated observations: three distinct reads inside the measured
	// five-second window are evidence even when the accepted report is unchanged.
	if len(x.conv) >= 4000 {
		return
	}
	x.conv = append(x.conv, row)
}

func leaseCheckOnly(v any) any {
	items, ok := v.([]any)
	if !ok {
		return v
	}
	for _, item := range items {
		m, ok := item.(map[string]any)
		if !ok {
			continue
		}
		if name, _ := m["name"].(string); name == "lease" {
			return m
		}
	}
	return nil
}

func (x *isolationRun) writeConvergence() {
	if x.records["AT10"] == nil {
		return
	}
	x.convMu.Lock()
	samples := append([]map[string]any(nil), x.conv...)
	first := x.firstCounted
	x.convMu.Unlock()
	doc := map[string]any{"run_id": x.records["AT10"].RunID, "build": x.records["AT10"].Build, "first_counted_member_byte": first, "samples": samples, "sample_cadence_ms": 250, "reference_window_ms": []int{5021, 5025}}
	raw, err := json.MarshalIndent(doc, "", "  ")
	if err == nil {
		_ = os.WriteFile(filepath.Join(x.dir, "convergence-timeline.json"), []byte(iso.Redact(string(raw))+"\n"), 0o644)
	}
	detail := first
	if detail == "" {
		detail = "no counted member byte during the sampled window"
	}
	note := iso.Observation{Name: "convergence_timeline", Detail: detail + "; samples=" + strconv.Itoa(len(samples))}
	for _, id := range []string{"AT10", "AT11", "AT12", "AT13"} {
		if x.records[id] != nil {
			x.records[id].Observations = append(x.records[id].Observations, note)
		}
	}
	names := []string{"RFC1918-10", "RFC1918-172", "RFC1918-192", "metadata", "public-prefix-internal", "deprecated-6to4"}
	var have, miss []string
	for _, name := range names {
		ok := false
		for _, check := range x.records["AT10"].Checks {
			if check.Name == name && check.Positive.Valid() {
				ok = true
			}
		}
		if ok {
			have = append(have, name)
		} else {
			miss = append(miss, name)
		}
	}
	x.records["AT10"].Observations = append(x.records["AT10"].Observations, iso.Observation{Name: "destination_positive_controls", Detail: "with_positive=" + strings.Join(have, ",") + "; without_positive=" + strings.Join(miss, ",")})
}

// memberGrants runs before any disruption. The only mutation in this window
// is the real control runtime's future-grant eligibility switch.
func (x *isolationRun) memberGrants() {
	c := iso.Check{Name: "provisional lease reports AWAITING_MEMBER_GRANTS", Status: iso.StatusFail, Owner: "w2-agent-core / w3-wire-nodes", Actual: "D-087 transition incomplete; see member-grants-transition.json"}
	evidence := map[string]any{"run_id": x.records["AT10"].RunID, "recipe_executed": false, "historical_isolation_ms": []int{4767, 5021, 5025}, "devstack_ms": []int{3980, 4112}}
	defer func() {
		evidence["status"] = c.Status
		x.extra("member-grants-transition.json", evidence)
		x.add("AT10", c)
	}()
	// The first counted flow drives ordinary initial FUP projection. It must
	// precede the stability window, or the flow itself can invalidate it.
	initial := x.proof(x.a1)
	evidence["initial_counted_forwarding"] = initial
	if !initial.Valid() {
		c.Actual = "D-087 initial native counted forwarding unavailable"
		return
	}
	var last json.RawMessage
	stableSince := time.Now()
	settling := []map[string]any{}
	wait, cancel := context.WithTimeout(x.ctx, 4*time.Minute)
	stable := waitUntil(wait, time.Second, func() bool {
		v, e := x.stack.MemberGrantInvariants(wait, x.r.nodeID)
		if e != nil {
			stableSince = time.Now()
			return false
		}
		if !bytes.Equal(v, last) {
			last = v
			stableSince = time.Now()
			settling = append(settling, map[string]any{"at": time.Now().UTC(), "snapshot": v})
		}
		return time.Since(stableSince) >= 65*time.Second
	})
	cancel()
	evidence["settling"] = settling
	if !stable {
		c.Actual = "D-087 initial invariants did not settle for 65 seconds"
		return
	}
	before, e := x.stack.MemberGrantInvariants(x.ctx, x.r.nodeID)
	evidence["before"] = before
	var inv struct {
		Node        []string          `json:"node"`
		Publication []string          `json:"publication"`
		Frozen      bool              `json:"frozen"`
		Bindings    []json.RawMessage `json:"bindings"`
		Offline     int               `json:"offline_seconds"`
	}
	if e != nil || json.Unmarshal(before, &inv) != nil || len(inv.Node) != 5 || inv.Node[1] != "ready" || inv.Node[2] != "passed" || inv.Node[3] != inv.Node[4] || inv.Frozen || len(inv.Bindings) == 0 || len(inv.Publication) != 2 || inv.Publication[0] != "published" || inv.Publication[1] != "active" || inv.Offline != 60 {
		c.Actual = "D-087 clean fixed-generation baseline absent"
		return
	}
	// Include the real baseline/meter/tunnel results before changing eligibility.
	x.observation(&c, x.a1)
	falseFlip, e := x.stack.SetMemberGrantsReady(x.ctx, false)
	evidence["false_flip"] = falseFlip
	if e != nil {
		c.Actual = "D-087 dedicated control seam unavailable"
		return
	}
	evidence["recipe_executed"] = true
	// Cleanup restores only eligibility after a failed measurement; it cannot
	// supply a qualifying receipt or change a failed result.
	defer func() { _, _ = x.stack.SetMemberGrantsReady(context.WithoutCancel(x.ctx), true) }()
	var events []GrantWireEvent
	var provisional, serving api.ObservationReport
	var provisionalEvent, servingEvent GrantWireEvent
	var emptyEvent, populatedEvent GrantWireEvent
	await := func(after time.Time, want bool) bool {
		wait, cancel := context.WithTimeout(x.ctx, 3*time.Minute)
		defer cancel()
		return waitUntil(wait, time.Second, func() bool {
			var err error
			events, err = x.stack.MemberGrantEvidence(wait)
			if err != nil {
				return false
			}
			for _, v := range events {
				report, ok := qualifyingGrantReport(v, x.r.nodeID, after, want)
				generation, genErr := report.AppliedConfigGeneration.Get()
				if !ok || genErr != nil || fmt.Sprint(generation) != inv.Node[3] {
					continue
				}
				id, _ := report.Lease.LeaseId.Get()
				for _, l := range events {
					if l.Kind != "lease" || l.Status != 200 || !l.Started.After(after) || l.Completed.After(v.Started) {
						continue
					}
					var lease struct {
						Signed struct {
							ID         uuid.UUID         `json:"lease_id"`
							Generation string            `json:"config_generation"`
							Members    []json.RawMessage `json:"members"`
						} `json:"signed"`
						Signatures []json.RawMessage `json:"signatures"`
					}
					if json.Unmarshal(l.Response, &lease) != nil || lease.Signed.ID != id || lease.Signed.Generation != inv.Node[3] || len(lease.Signatures) == 0 || (len(lease.Signed.Members) == 0) != want {
						continue
					}
					if want {
						provisional, provisionalEvent, emptyEvent = report, v, l
					} else {
						serving, servingEvent, populatedEvent = report, v, l
					}
					return true
				}
			}
			return false
		})
	}
	defer func() { x.extra("member-grants-wire.json", events) }()
	provisionalOK := await(falseFlip.Completed, true)
	evidence["provisional_receipt"], evidence["empty_lease"] = provisionalEvent, emptyEvent
	middle, middleErr := x.stack.MemberGrantInvariants(x.ctx, x.r.nodeID)
	evidence["provisional_invariants"] = middle
	if !provisionalOK {
		c.Actual = "D-087 no accepted qualifying report joined to the natural empty lease"
		return
	}
	trueFlip, e := x.stack.SetMemberGrantsReady(x.ctx, true)
	evidence["true_flip"] = trueFlip
	if e != nil {
		c.Actual = "D-087 true flip failed"
		return
	}
	servingOK := await(trueFlip.Completed, false)
	evidence["serving_receipt"], evidence["populated_lease"] = servingEvent, populatedEvent
	if servingOK {
		c.Positive = x.proof(x.a1)
	}
	after, afterErr := x.stack.MemberGrantInvariants(x.ctx, x.r.nodeID)
	evidence["after"], evidence["counted_forwarding"] = after, c.Positive
	events, e = x.stack.MemberGrantEvidence(x.ctx)
	same := middleErr == nil && afterErr == nil && bytes.Equal(before, middle) && bytes.Equal(before, after)
	emptyID, _ := provisional.Lease.LeaseId.Get()
	fullID, _ := serving.Lease.LeaseId.Get()
	distinct := provisional.ReportId != serving.ReportId && emptyID != fullID
	hashes, wireOK := 0, e == nil
	for _, v := range events {
		for _, pair := range [][2]string{{v.RequestWire, v.RequestSHA256}, {v.ResponseWire, v.ResponseSHA256}} {
			if pair[0] != "" {
				sum := sha256.Sum256([]byte(pair[0]))
				hashes++
				wireOK = wireOK && hex.EncodeToString(sum[:]) == pair[1]
			}
		}
	}
	duration := servingEvent.Completed.Sub(trueFlip.Completed).Milliseconds()
	evidence["proof"] = map[string]any{"invariants_byte_equal": same, "distinct_reports_and_leases": distinct, "empty_lease_report_join": provisionalOK, "populated_lease_report_join": servingOK, "wire_hashes": hashes, "wire_hashes_valid": wireOK, "true_to_serving_receipt_ms": duration, "generation": inv.Node[3]}
	if same && distinct && wireOK && servingOK && c.Positive.Valid() {
		c.Status = iso.StatusPass
		c.Owner = ""
		c.Actual = fmt.Sprintf("D-087 real false/true future-grant transition; accepted reports joined to empty/populated signed leases; fixed generation %s and byte-identical invariants; true to accepted serving %d ms; independent native admission counter increased", inv.Node[3], duration)
	}
}

func (x *isolationRun) noteEvaluator() {
	if x.records["AT13"] == nil {
		return
	}
	root := moduleRoot()
	sum := sha256.New()
	for _, name := range []string{"capture.go", "capture_review_test.go"} {
		body, err := os.ReadFile(filepath.Join(root, "tests/e2e/at/isolation", name))
		if err != nil {
			x.records["AT13"].Observations = append(x.records["AT13"].Observations, iso.Observation{Name: "capture_evaluator", Detail: "unavailable"})
			return
		}
		_, _ = sum.Write(body)
	}
	x.records["AT13"].Observations = append(x.records["AT13"].Observations, iso.Observation{Name: "capture_evaluator", Detail: "SHA256(concatenated capture.go, capture_review_test.go)=" + hex.EncodeToString(sum.Sum(nil)) + "; singular/plural parser from follow-up 2 remains in force"})
}

