func (x *isolationRun) foreignRedirect() {
	c := iso.Check{Name: "foreign ingress redirect containment and D-096 recovery", Positive: x.proof(x.a1), Status: iso.StatusBlocked, Owner: "w2-agent-core / w1-netlab"}
	defer func() { x.add("AT10", c) }()
	if !iso.ControlObservationReady(x.dir, x.records["AT10"].RunID, x.lastControlStart, x.waitControl) {
		c.Actual = "current accepted observation and drained retry queue not established after control restoration; no injection"
		return
	}
	if !c.Positive.Valid() {
		c.Actual = "pre-injection counted control unavailable; no injection"
		return
	}
	initial := x.networkSnapshot("before injection")
	var initialReport struct {
		Applied string `json:"applied_config_generation"`
	}
	initialBody, _ := initial["observation"].(json.RawMessage)
	_ = json.Unmarshal(initialBody, &initialReport)
	initialGeneration, _ := strconv.ParseUint(initialReport.Applied, 10, 64)
	rows := []map[string]any{initial}
	cap := x.continuousCapture(x.r.lab.node, "any", "udp port 9 or tcp port 443", "redirect-node-capture.txt", 75)
	defer func() {
		x.finishCapture(cap)
		x.extra("foreign-redirect.json", map[string]any{"run_id": x.records["AT10"].RunID, "rows": rows, "restoration_owner": "native NetBird IPv4 owner; no harness route/address writes or link raise", "assisted": false})
	}()
	_ = exec.Command("docker", "exec", "-d", x.a1.lab.member, "/tmp/isolation-probe", "pulse", x.a1.originIP(), "70").Run()
	time.Sleep(300 * time.Millisecond)
	at := time.Now()
	out, e := x.r.lab.docker(x.r.lab.node, "sh", "-c", "tc qdisc add dev fvmb0 clsact && tc filter add dev fvmb0 ingress protocol ip pref 49152 flower ip_proto udp dst_ip "+x.a1.originIP()+" dst_port 9 action mirred egress redirect dev fvup0")
	rows = append(rows, map[string]any{"label": "inject clsact mirred", "start": at.UTC().Format(time.RFC3339Nano), "end": time.Now().UTC().Format(time.RFC3339Nano), "output": string(out), "ok": e == nil, "creator": "this TEST ONLY isolation harness"})
	contained := false
	for range 30 {
		row := x.networkSnapshot("containment wait")
		rows = append(rows, row)
		raw, _ := json.Marshal(row)
		if strings.Contains(string(raw), "TC_FOREIGN_FILTER") && strings.Contains(row["readback"].(string), "serving 0") {
			contained = true
			break
		}
		time.Sleep(300 * time.Millisecond)
	}
	dirtyAt := time.Now().UTC()
	response := x.capacityGeneration(206000000, isolationCheckNote(&c))
	rows = append(rows, map[string]any{"label": "publish dirty newer generation", "at": dirtyAt.Format(time.RFC3339Nano), "response": response})
	dirtyAccepted := false
	for range 12 {
		row := x.networkSnapshot("dirty newer generation")
		rows = append(rows, row)
		var report struct {
			Observed   time.Time `json:"observed_at"`
			Forwarding bool      `json:"member_forwarding_enabled"`
			Errors     []struct {
				Stage, Code, Message string
				At                   time.Time `json:"observed_at"`
			} `json:"errors"`
		}
		body, _ := row["observation"].(json.RawMessage)
		_, _, _, generation := x.r.desiredMemberView()
		candidateGeneration, _ := strconv.ParseUint(generation, 10, 64)
		if candidateGeneration > initialGeneration && json.Unmarshal(body, &report) == nil && !report.Forwarding && report.Observed.After(dirtyAt) {
			for _, failure := range report.Errors {
				if failure.Stage == "apply_candidate" && failure.Code == "TC_FOREIGN_FILTER" && failure.Message == "candidate_generation="+generation+" verified=false" {
					dirtyAccepted = true
				}
			}
		}
		if dirtyAccepted {
			break
		}
		time.Sleep(500 * time.Millisecond)
	}
	rows = append(rows, map[string]any{"label": "dirty acceptance boundary", "at": time.Now().UTC(), "accepted": dirtyAccepted, "budget": "unchanged maximum 12 samples at 500ms; cleanup on exhaustion does not qualify"})
	at = time.Now()
	out, e = x.r.lab.docker(x.r.lab.node, "tc", "qdisc", "del", "dev", "fvmb0", "clsact")
	rows = append(rows, map[string]any{"label": "remove all injected objects", "start": at.UTC().Format(time.RFC3339Nano), "end": time.Now().UTC().Format(time.RFC3339Nano), "output": string(out), "ok": e == nil})
	rows = append(rows, x.networkSnapshot("fresh removal read"))
	rows = append(rows, map[string]any{"label": "publish clean newer generation", "at": time.Now().UTC().Format(time.RFC3339Nano), "response": x.capacityGeneration(207000000, isolationCheckNote(&c))})
	recovered := false
	for range 80 {
		row := x.networkSnapshot("recovery wait")
		rows = append(rows, row)
		if strings.Contains(row["readback"].(string), "serving 1") {
			body, _ := row["observation"].(json.RawMessage)
			var report map[string]any
			_ = json.Unmarshal(body, &report)
			if report["member_forwarding_enabled"] == true {
				recovered = true
				break
			}
		}
		time.Sleep(500 * time.Millisecond)
	}
	after := x.proof(x.a1)
	rows = append(rows, map[string]any{"label": "final counted control", "at": time.Now().UTC().Format(time.RFC3339Nano), "positive": after})
	rows = append(rows, x.networkSnapshot("final recovered state"))
	x.captureApplied()
	c.Observations = append(c.Observations, iso.Observation{Name: "recovered_counted_control", Detail: mustJSON(after)})
	c.Actual = fmt.Sprintf("contained=%t dirty_accepted=%t recovered=%t counted=%t; unattended native topology recovery; six-assertion review follows receiver export", contained, dirtyAccepted, recovered, after.Valid())
	if !contained || !recovered || !after.Valid() {
		c.Status = iso.StatusFail
	}
}
func (x *isolationRun) freezeIdentity() {
	x.retainReasonLogs("before-clone")
	leaseBefore, beforeOK := x.readNodeLease()
	agentIdentity := x.agentStopIdentity(x.r.lab.node)
	at := time.Now()
	x.cloneAttempted = true
	fixture, err := x.stack.StartClonedIdentityFixture(x.ctx, "node")
	completed := time.Now()
	leaseAfter, afterOK := x.readNodeLease()
	state, stateErr := exec.Command("docker", "inspect", "--format={{json .State}}", x.r.lab.node).Output()
	var lifecycle struct {
		StartedAt  time.Time `json:"StartedAt"`
		FinishedAt time.Time `json:"FinishedAt"`
	}
	stateOK := stateErr == nil && json.Unmarshal(state, &lifecycle) == nil && lifecycle.FinishedAt.After(at) && lifecycle.StartedAt.After(lifecycle.FinishedAt)
	evidence := map[string]any{"agent_stop": x.agentStopReceipt(x.r.lab.node, agentIdentity), "agent_budget_seconds": 15, "container_grace_seconds": 25, "started_at": at.UTC().Format(time.RFC3339Nano), "completed_at": completed.UTC(), "fixture_duration_ns": strconv.FormatInt(completed.Sub(at).Nanoseconds(), 10), "before_lease": leaseBefore, "after_lease": leaseAfter, "before_available": beforeOK, "after_available": afterOK, "stored_lease_survived_restart": beforeOK && afterOK && leaseBefore.LeaseID == leaseAfter.LeaseID && leaseBefore.MonoSent == leaseAfter.MonoSent, "container_stop_available": stateOK, "owner": "ENR-02 / ENR-03; this is the consumer latch observation only"}
	if stateOK {
		evidence["container_finished_at"], evidence["container_started_at"] = lifecycle.FinishedAt, lifecycle.StartedAt
		evidence["container_stopped_duration_ns"] = strconv.FormatInt(lifecycle.StartedAt.Sub(lifecycle.FinishedAt).Nanoseconds(), 10)
	}
	defer func() { x.extra("identity-freeze.json", evidence) }()
	if err != nil {
		evidence["status"] = "blocked"
		evidence["detail"] = err.Error()
		return
	}
	var rows []map[string]any
	for range 90 {
		obs, e := fixture.Observe(x.ctx)
		row := x.networkSnapshot("clone acceptance window")
		row["clone_observation"] = obs
		if e != nil {
			row["clone_read_error"] = e.Error()
		}
		rows = append(rows, row)
		if obs.MappingFrozen && strings.Contains(row["readback"].(string), "identity_frozen") {
			time.Sleep(3 * time.Second)
			rows = append(rows, x.networkSnapshot("freeze latch held"))
			break
		}
		time.Sleep(time.Second)
	}
	evidence["rows"] = rows
	evidence["status"] = "requires receiver correlation"
	evidence["fixture"] = "same enrolled incarnation presented from a second lab network; not a newly enrolled identity"
}

