// Read-only snapshot of state that production persists only after verified Apply.
func (x *isolationRun) captureApplied() {
	dir := x.t.TempDir()
	for _, name := range []string{"agent.db", "agent.db-wal", "agent.db-shm"} {
		_ = exec.Command("docker", "cp", x.r.lab.node+":/var/lib/vpn-node/state/"+name, filepath.Join(dir, name)).Run()
	}
	db, err := sql.Open("sqlite", "file:"+filepath.Join(dir, "agent.db")+"?mode=ro")
	if err != nil {
		return
	}
	defer db.Close()
	result := map[string]any{"read_at": time.Now().UTC().Format(time.RFC3339Nano), "source": "read-only node SQLite snapshot; production persistence after verified Apply"}
	for _, key := range []string{"retained_applied", "member_path"} {
		var raw string
		if db.QueryRow(`SELECT value FROM meta WHERE key=?`, key).Scan(&raw) == nil && json.Valid([]byte(raw)) {
			result[key] = json.RawMessage(raw)
		}
	}
	var applied int64
	_ = db.QueryRow(`SELECT applied_generation FROM desired WHERE id=1`).Scan(&applied)
	result["applied_generation"] = fmt.Sprint(applied)
	lease, ok := x.readNodeLease()
	if ok {
		result["lease"] = lease
	}
	x.extra("recovery-applied-state.json", result)
}

// Read-only central consumer. Every accepted report is retained, including
// ones missed by the HTTP receiver; the report's own lease supplies its join.
func (x *isolationRun) startHoldCapture() {
	x.holdStop, x.holdDone = make(chan struct{}), make(chan struct{})
	go func() {
		defer close(x.holdDone)
		conn, err := x.r.lab.db(x.ctx)
		if err != nil {
			x.t.Error("hold capture connection", err)
			return
		}
		defer conn.Close(x.ctx)
		seen := map[string]bool{}
		since := time.Time{}
		capture := func() {
			rows, err := conn.Query(x.ctx, `SELECT o.report_id::text,o.received_at,jsonb_build_object(
    'report',o.report_payload,'observation_id',o.id,'received_at',o.received_at,
    'desired_generation_at_read',n.desired_config_generation::text,
    'applied_generation_at_read',n.applied_config_generation::text,
    'lease',s.envelope,'stored_lease_generation',s.policy_generation::text,
    'sample',CASE WHEN h.report_id IS NULL THEN NULL ELSE to_jsonb(h) || jsonb_build_object(
      'applied_generation',h.applied_generation::text,'lease_generation',h.lease_generation::text,
      'reported_steps',h.reported_steps::text,'reported_elapsed_ms',h.reported_elapsed_ms::text) END,
    'incident',to_jsonb(i))
    FROM node_observations o JOIN nodes n ON n.id=o.node_id
    LEFT JOIN serving_leases s ON s.id::text=o.report_payload#>>'{lease,lease_id}' AND s.node_id=o.node_id AND s.incarnation_id=o.incarnation_id
    LEFT JOIN node_generation_hold_reports h ON h.node_id=o.node_id AND h.incarnation_id=o.incarnation_id AND h.report_id=o.report_id
    LEFT JOIN node_generation_holds i ON i.id=h.hold_id
    WHERE o.node_id=$1 AND o.received_at >= $2 ORDER BY o.received_at,o.report_id`, x.r.nodeID, since)
			if err != nil {
				x.t.Error("hold capture query", err)
				return
			}
			var batch []map[string]any
			for rows.Next() {
				var id string
				var at time.Time
				var raw []byte
				if err = rows.Scan(&id, &at, &raw); err != nil {
					x.t.Error(err)
					break
				}
				if at.After(since) {
					since = at
				}
				if seen[id] {
					continue
				}
				seen[id] = true
				var row map[string]any
				if err = json.Unmarshal(raw, &row); err != nil {
					x.t.Error(err)
					continue
				}
				batch = append(batch, row)
			}
			err = rows.Err()
			rows.Close()
			if err != nil {
				x.t.Error(err)
			}
			for _, row := range batch {
				row["read_at"] = time.Now().UTC().Format(time.RFC3339Nano)
				raw, _ := json.Marshal(row["report"])
				var report api.ObservationReport
				if json.Unmarshal(raw, &report) != nil {
					x.t.Error("hold report decode")
					continue
				}
				if isolationHoldMarker(report) {
					gen, _ := strconv.ParseUint(row["desired_generation_at_read"].(string), 10, 64)
					cause, e := nodes.PublicationDataPathFailure(x.ctx, conn, report, gen, time.Now().UTC())
					row["publication_data_path_failure"], row["classification_available"] = cause, e == nil
					// Read-only replay of the same original checks/errors in reverse order.
					// Never posted to central and never called an additional observation.
					for a, b := 0, len(report.Checks)-1; a < b; a, b = a+1, b-1 {
						report.Checks[a], report.Checks[b] = report.Checks[b], report.Checks[a]
					}
					for a, b := 0, len(report.Errors)-1; a < b; a, b = a+1, b-1 {
						report.Errors[a], report.Errors[b] = report.Errors[b], report.Errors[a]
					}
					reverse, re := nodes.PublicationDataPathFailure(x.ctx, conn, report, gen, time.Now().UTC())
					row["reverse_array_replay_cause"], row["reverse_array_replay_available"] = reverse, re == nil
					var ops []byte
					e = conn.QueryRow(x.ctx, `SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'kind',kind,'status',status,'desired_generation',desired_generation::text,'steps',steps,'created_at',created_at,'completed_at',completed_at)),'[]'::jsonb) FROM operations WHERE resource_id=$1 OR resource_id IN (SELECT id FROM exits WHERE node_id=$1)`, x.r.nodeID).Scan(&ops)
					if e == nil {
						row["operations_at_read"] = json.RawMessage(ops)
					} else {
						x.t.Error("hold operations", e)
					}
				}
				x.holdRows = append(x.holdRows, row)
			}
		}
		ticker := time.NewTicker(25 * time.Millisecond)
		defer ticker.Stop()
		for {
			capture()
			select {
			case <-x.ctx.Done():
				return
			case <-x.holdStop:
				capture()
				return
			case <-ticker.C:
			}
		}
	}()
}

func isolationHoldMarker(r api.ObservationReport) bool {
	missing := false
	for _, v := range r.ForwardingBlockReasons {
		if v == api.ForwardingBlockReasonPolicyMissing {
			missing = true
		}
	}
	if !missing {
		return false
	}
	for _, c := range r.Checks {
		code, _ := c.ErrorCode.Get()
		if c.Name == api.NodeCheckNameLease && code == api.ErrorCodeSTALEGENERATION {
			return true
		}
	}
	for _, e := range r.Errors {
		if e.Stage == "lease" && e.Code == api.ErrorCodeSTALEGENERATION {
			return true
		}
	}
	return false
}

func (x *isolationRun) holdSnapshot() json.RawMessage {
	conn, err := x.r.lab.db(x.ctx)
	if err != nil {
		x.t.Error(err)
		return nil
	}
	defer conn.Close(x.ctx)
	var raw []byte
	err = conn.QueryRow(x.ctx, `SELECT jsonb_build_object('read_at',clock_timestamp(),
  'incidents',coalesce((SELECT jsonb_agg(to_jsonb(h) ORDER BY first_seen_at) FROM node_generation_holds h WHERE node_id=$1),'[]'::jsonb),
  'samples',coalesce((SELECT jsonb_agg(to_jsonb(r) || jsonb_build_object('applied_generation',applied_generation::text,'lease_generation',lease_generation::text,'reported_steps',reported_steps::text,'reported_elapsed_ms',reported_elapsed_ms::text)) FROM node_generation_hold_reports r WHERE node_id=$1),'[]'::jsonb),
  'audits',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'action',action,'occurred_at',occurred_at,'result',result,'evidence',after_diff) ORDER BY occurred_at) FROM audit_events WHERE action='node.generation_hold.escalated' AND resource='node:'||$1::text),'[]'::jsonb))`, x.r.nodeID).Scan(&raw)
	if err != nil {
		x.t.Error("hold snapshot", err)
		return nil
	}
	return raw
}

func (x *isolationRun) finishHoldCapture() {
	if x.holdStop == nil {
		return
	}
	close(x.holdStop)
	<-x.holdDone
	x.extra("generation-holds-central.json", map[string]any{"run_id": x.records["AT10"].RunID, "reports": x.holdRows, "final": x.holdSnapshot(),
		"scope": "Immutable accepted reports and own signed leases, read-only live classification and reverse-array replay. desired_generation_at_read and operations_at_read are polling snapshots, not transaction-time values. No report is manufactured or replayed into ingestion."})
}

// One attempt using the existing admin capacity change, Docker control cut,
// direct pidfd stop and supervisor start. No lease/desired fault hook is added.
func (x *isolationRun) generationHoldCut() {
	evidence := map[string]any{"run_id": x.records["AT10"].RunID, "status": "not exercised", "kernel_reboot": "not exercised: AT13 operator matrix"}
	defer func() { x.extra("generation-hold-control-cut.json", evidence) }()
	positive := x.proof(x.a1)
	evidence["positive"] = positive
	if !positive.Valid() {
		evidence["reason"] = "no counted control before the attempt"
		return
	}
	conn, err := x.r.lab.db(x.ctx)
	if err != nil {
		x.t.Error(err)
		return
	}
	defer conn.Close(x.ctx)
	admin, err := x.r.lab.login(x.ctx, "e2e-admin", "admin")
	if err != nil {
		return
	}
	x.admin = admin
	path := x.r.lab.public + "/api/v1/admin/nodes/" + x.r.nodeID.String()
	get, e := admin.call(x.ctx, "GET", path, nil, nil)
	if e != nil || get.Status != 200 {
		return
	}
	start := time.Now().UTC()
	capacity := map[string]any{"capacity": map[string]any{"down_bps": 205000000, "up_bps": 200000000, "member_down_bps_cap": 100000000, "member_up_bps_cap": 100000000}}
	write := admin.writeNode(x.ctx, "PATCH", path, path, capacity, get.Header.Get("ETag"), nodeFieldsMatch(capacity), []int{200, 202}, isolationMapNote(evidence))
	patch, e := write.Reply, write.Err
	evidence["patch"] = map[string]any{"at": start, "response": json.RawMessage(patch.Body), "status": patch.Status, "ok": e == nil, "timed_assertion_origin": "logical command start before first write; retries do not reset incident lower bound"}
	if !write.accepted(200, 202) {
		return
	}
	var incident, reportID, leaseID, leaseGen string
	deadline := time.Now().Add(15 * time.Second)
	found := false
	for time.Now().Before(deadline) {
		err = conn.QueryRow(x.ctx, `SELECT h.id::text,r.report_id::text,r.lease_id::text,r.lease_generation::text FROM node_generation_holds h JOIN node_generation_hold_reports r ON r.hold_id=h.id WHERE h.node_id=$1 AND h.first_seen_at >= $2 AND h.ended_at IS NULL ORDER BY h.first_seen_at DESC LIMIT 1`, x.r.nodeID, start).Scan(&incident, &reportID, &leaseID, &leaseGen)
		if err == nil {
			found = true
			break
		}
		time.Sleep(10 * time.Millisecond)
	}
	if !found {
		evidence["reason"] = "no new accepted open hold in the single 15-second attempt; no transport seam or retry added"
		return
	}
	pausedAt := time.Now().UTC()
	out, err := exec.Command("docker", "pause", x.r.lab.control, x.r.lab.prefix+"-worker").CombinedOutput()
	evidence["cut"] = map[string]any{"start": pausedAt, "end": time.Now().UTC(), "ok": err == nil, "output": string(out)}
	restored := false
	defer func() {
		if !restored {
			x.lastControlStart = time.Now().UTC()
			_ = exec.Command("docker", "unpause", x.r.lab.control, x.r.lab.prefix+"-worker").Run()
			x.waitControl()
		}
	}()
	if err != nil {
		return
	}
	evidence["incident_id"], evidence["report_id"], evidence["lease_id"], evidence["lease_generation"] = incident, reportID, leaseID, leaseGen
	held, ok := x.readNodeLease()
	evidence["held_lease"], evidence["held_available"] = held, ok
	evidence["before_cut_snapshot"] = x.holdSnapshot()
	if !ok || held.LeaseID != leaseID {
		evidence["reason"] = "node renewed before the existing cut completed; long hold not exercised"
		return
	}
	evidence["status"] = "attempted"
	// Collect independent denial; unavailable counters never become a zero.
	denial := iso.Check{}
	route, result, ingress, delivered := x.capturedConnect(x.a1, x.a1.lab.prefix+"-origin", x.a1.originIP(), 443, &denial)
	evidence["denial"] = map[string]any{"route": route, "result": result, "ingress": ingress, "delivered": delivered, "observations": denial.Observations}
	evidence["kernel_during_cut"] = x.networkSnapshot("generation hold during control loss")
	x.sleep(time.Until(pausedAt.Add(35 * time.Second)))
	evidence["before_direct_stop"] = x.holdSnapshot()
	x.retainReasonLogs("before-hold-stop")
	stoppedAt := time.Now().UTC()
	raw, stopErr := x.r.lab.docker(x.r.lab.node, "/tmp/isolation-probe", "agent-stop-sample")
	evidence["direct_stop"] = map[string]any{"start": stoppedAt, "end": time.Now().UTC(), "ok": stopErr == nil, "output": iso.Redact(string(raw))}
	evidence["after_direct_stop"] = x.holdSnapshot()
	stored, storedOK := x.readNodeLease()
	evidence["stored_after_stop"], evidence["stored_after_stop_available"] = stored, storedOK
	restartAt := time.Now().UTC()
	err = x.stack.Service(x.ctx, "start", "/usr/local")
	evidence["process_restart"] = map[string]any{"start": restartAt, "end": time.Now().UTC(), "ok": err == nil}
	x.sleep(4 * time.Second)
	restoredAt := time.Now().UTC()
	x.lastControlStart = restoredAt
	err = exec.Command("docker", "unpause", x.r.lab.control, x.r.lab.prefix+"-worker").Run()
	restored = err == nil
	evidence["restoration"] = map[string]any{"start": restoredAt, "end": time.Now().UTC(), "ok": err == nil}
	ready := x.waitControl()
	evidence["restored_ready"] = ready
	evidence["after_restoration"] = x.holdSnapshot()
	evidence["recovered_counted"] = x.proof(x.a1)
}

// D-102: consume devstack 27's unchanged, bounded matching-renewal seam.
// The only extra fault removes an executable inside this owned container;
// no signed document, observation, central row or node ruleset is edited.
func (x *isolationRun) populatedHolds() {
	evidence := map[string]any{"run_id": x.records["AT13"].RunID, "scope": "TEST ONLY three explicit incidents; third attempts central age fallback; original capacity commands; devstack 27 seam"}
	attempts := []map[string]any{}
	defer func() {
		evidence["attempts"] = attempts
		raw, err := x.stack.GenerationHoldSnapshot(x.ctx, x.r.nodeID)
		if err == nil {
			evidence["final"] = raw
		}
		x.extra("populated-holds.json", evidence)
	}()
	for n := 1; n <= 3; n++ {
		row := map[string]any{"attempt": n, "status": "not exercised", "started_at": time.Now().UTC()}
		attempts = append(attempts, row)
		if !x.populatedHold(n, row) {
			// A later incident requires recovery; do not turn setup failure into
			// a replacement attempt or claim an unexecuted second arm.
			for later := n + 1; later <= 3; later++ {
				attempts = append(attempts, map[string]any{"attempt": later, "status": "not exercised", "reason": "preceding incident recovery unavailable"})
			}
			return
		}
	}
}

func (x *isolationRun) populatedHold(n int, row map[string]any) bool {
	positive := x.proof(x.a1)
	row["positive"] = positive
	if !positive.Valid() {
		row["reason"] = "counted pre-hold control unavailable"
		return false
	}
	conn, err := x.r.lab.db(x.ctx)
	if err != nil {
		row["reason"] = "central read unavailable"
		return false
	}
	defer conn.Close(x.ctx)
	waitFor := func(seconds int, f func() bool) bool {
		ctx, cancel := context.WithTimeout(x.ctx, time.Duration(seconds)*time.Second)
		defer cancel()
		return waitUntil(ctx, 250*time.Millisecond, f)
	}
	var base, oldLease string
	var before json.RawMessage
	ready := waitFor(75, func() bool {
		return conn.QueryRow(x.ctx, `SELECT s.policy_generation::text,s.id::text,jsonb_build_object(
 'node_id',n.id,'incarnation_id',o.incarnation_id,'report_id',o.report_id,'received_at',o.received_at,
 'lease_id',s.id,'generation',s.policy_generation::text,'expires_at',s.expires_at,
 'member_count',(SELECT count(DISTINCT member_id) FROM serving_lease_members WHERE lease_id=s.id))
 FROM nodes n JOIN LATERAL(SELECT * FROM node_observations WHERE node_id=n.id AND incarnation_id=n.current_incarnation_id ORDER BY received_at DESC,id DESC LIMIT 1)o ON true
 JOIN serving_leases s ON s.id::text=o.report_payload->'lease'->>'lease_id'
 WHERE n.id=$1 AND o.member_forwarding_enabled AND s.policy_generation=o.applied_generation
 AND n.desired_config_generation=o.applied_generation
 AND (SELECT count(DISTINCT member_id) FROM serving_lease_members WHERE lease_id=s.id)>=2
 AND s.expires_at>clock_timestamp()+interval '50 seconds'`, x.r.nodeID).Scan(&base, &oldLease, &before) == nil
	})
	row["before"] = before
	if !ready {
		row["reason"] = "fresh matching populated lease with >50 seconds remaining unavailable"
		return false
	}
	arm, err := x.stack.ArmMatchingLeaseHold(x.ctx, "node", base, 45*time.Second)
	row["arm"] = arm
	if err != nil {
		row["reason"] = "seam arm unavailable: " + err.Error()
		return false
	}
	row["status"] = "attempted"
	defer func() {
		_ = x.stack.ReleaseMatchingLeaseHold(context.WithoutCancel(x.ctx), "node", arm.ID)
		ev, e := x.stack.MatchingLeaseHold(x.ctx, "node", arm.ID)
		if e == nil {
			row["proxy"] = ev
		}
	}()
	path := x.r.lab.public + "/api/v1/admin/nodes/" + x.r.nodeID.String()
	get, err := x.admin.call(x.ctx, "GET", path, nil, nil)
	if err != nil || get.Status != 200 {
		row["reason"] = "node GET unavailable"
		return false
	}
	start := time.Now().UTC()
	capacity := map[string]any{"capacity": map[string]any{"down_bps": 210000000 + n*1000000, "up_bps": 200000000, "member_down_bps_cap": 100000000, "member_up_bps_cap": 100000000}}
	write := x.admin.writeNode(x.ctx, "PATCH", path, path, capacity, get.Header.Get("ETag"), nodeFieldsMatch(capacity), []int{202}, isolationMapNote(row))
	patch, err := write.Reply, write.Err
	row["command"] = map[string]any{"start": start, "end": time.Now().UTC(), "status": patch.Status, "response": json.RawMessage(patch.Body), "ok": err == nil, "timed_assertion_origin": "logical command start before first write; retries do not reset incident lower bound"}
	if !write.accepted(202) {
		row["reason"] = "capacity command not accepted"
		return false
	}
	var operation struct {
		ID uuid.UUID `json:"operation_id"`
	}
	if json.Unmarshal(patch.Body, &operation) == nil && operation.ID != uuid.Nil {
		readback, e := x.admin.call(x.ctx, "GET", x.r.lab.public+"/api/v1/admin/operations/"+operation.ID.String(), nil, nil)
		row["command_readback"] = map[string]any{"at": time.Now().UTC(), "status": readback.Status, "ok": e == nil, "response": json.RawMessage(readback.Body)}
	}
	var incident string
	found := waitFor(15, func() bool {
		return conn.QueryRow(x.ctx, `SELECT h.id::text FROM node_generation_holds h JOIN node_generation_hold_reports r ON r.hold_id=h.id WHERE h.node_id=$1 AND h.ended_at IS NULL AND h.first_seen_at >= $2 AND r.lease_id=$3 ORDER BY h.first_seen_at DESC LIMIT 1`, x.r.nodeID, start, oldLease).Scan(&incident) == nil
	})
	row["incident_id"] = incident
	snapshot := func(label string) {
		raw, e := x.stack.GenerationHoldSnapshot(x.ctx, x.r.nodeID)
		if e == nil {
			row[label] = raw
		}
	}
	snapshot("first_hold")
	if !found {
		row["reason"] = "no accepted incident for the retained populated lease"
		return false
	}
	if n == 3 {
		row["purpose"] = "central_age_fallback"
		snapshot("before_stop")
		stopStart := time.Now().UTC()
		out, stopErr := x.r.lab.docker(x.r.lab.node, "/tmp/isolation-probe", "agent-stop-sample")
		row["stop"] = map[string]any{"start": stopStart, "end": time.Now().UTC(), "ok": stopErr == nil, "output": iso.Redact(string(out))}
		snapshot("after_stop")
		ev, e := x.stack.MatchingLeaseHold(x.ctx, "node", arm.ID)
		row["proxy_after_stop"], row["proxy_after_stop_available"] = ev, e == nil
		// Observe central's own clock and original audit. An early alarm makes
		// this attempt ineligible; never suppress, edit or replace its report.
		var auditID string
		row["fallback_audit_observed"] = waitFor(35, func() bool {
			return conn.QueryRow(x.ctx, `SELECT id::text FROM audit_events WHERE action='node.generation_hold.escalated' AND after_diff->>'incident_id'=$1 ORDER BY occurred_at LIMIT 1`, incident).Scan(&auditID) == nil
		})
		row["fallback_audit_id"] = auditID
		snapshot("fallback")
		restartAt := time.Now().UTC()
		err = x.stack.Service(x.ctx, "start", "/usr/local")
		row["restart"] = map[string]any{"start": restartAt, "end": time.Now().UTC(), "ok": err == nil}
	} else {
		var alarmReport string
		alarm := waitFor(12, func() bool {
			return conn.QueryRow(x.ctx, `SELECT report_id::text FROM node_generation_hold_reports WHERE hold_id=$1 AND summary_valid AND reported_alarm ORDER BY reported_steps LIMIT 1`, incident).Scan(&alarmReport) == nil
		})
		row["alarm_observed"], row["alarm_report_id"] = alarm, alarmReport
		snapshot("alarm")
	}
	denial := iso.Check{}
	route, result, ingress, delivered := x.capturedConnect(x.a1, x.a1.lab.prefix+"-origin", x.a1.originIP(), 443, &denial)
	row["denial"] = map[string]any{"route": route, "result": result, "ingress": ingress, "delivered": delivered, "observations": denial.Observations}
	if n == 1 {
		faultStart := time.Now().UTC()
		out, faultErr := x.r.lab.docker(x.r.lab.node, "sh", "-ec", `p=$(command -v conntrack); test -n "$p"; test ! -e /var/lib/vpn-node/e2e/hold-conntrack; printf '%s' "$p" > /var/lib/vpn-node/e2e/hold-conntrack-path; mv "$p" /var/lib/vpn-node/e2e/hold-conntrack`)
		row["unrelated_fault"] = map[string]any{"start": faultStart, "end": time.Now().UTC(), "ok": faultErr == nil, "output": string(out), "scope": "TEST ONLY temporarily absent conntrack executable inside owned node"}
		restored := false
		restore := func() {
			if restored {
				return
			}
			_, e := x.r.lab.docker(x.r.lab.node, "sh", "-ec", `if test -e /var/lib/vpn-node/e2e/hold-conntrack; then p=$(cat /var/lib/vpn-node/e2e/hold-conntrack-path); mv /var/lib/vpn-node/e2e/hold-conntrack "$p"; fi`)
			row["fault_restored"] = map[string]any{"at": time.Now().UTC(), "ok": e == nil}
			restored = e == nil
		}
		defer restore()
		var faultReport string
		if faultErr == nil {
			row["unrelated_report_observed"] = waitFor(8, func() bool {
				return conn.QueryRow(x.ctx, `SELECT o.report_id::text FROM node_observations o JOIN node_generation_hold_reports h USING(node_id,incarnation_id,report_id) WHERE h.hold_id=$1 AND o.received_at>$2 AND EXISTS(SELECT 1 FROM jsonb_array_elements(o.report_payload->'errors') e WHERE e->>'stage'='apply' AND e->>'code'='ISOLATION_POLICY_INVALID') ORDER BY o.received_at LIMIT 1`, incident, faultStart).Scan(&faultReport) == nil
			})
		}
		row["unrelated_report_id"] = faultReport
		snapshot("unrelated_failure")
		restore()
		snapshot("before_stop")
		x.retainReasonLogs("before-populated-hold-stop")
		stopStart := time.Now().UTC()
		out, stopErr := x.r.lab.docker(x.r.lab.node, "/tmp/isolation-probe", "agent-stop-sample")
		row["stop"] = map[string]any{"start": stopStart, "end": time.Now().UTC(), "ok": stopErr == nil, "output": iso.Redact(string(out))}
		snapshot("after_stop")
		ev, e := x.stack.MatchingLeaseHold(x.ctx, "node", arm.ID)
		row["proxy_after_stop"], row["proxy_after_stop_available"] = ev, e == nil
		restartAt := time.Now().UTC()
		err = x.stack.Service(x.ctx, "start", "/usr/local")
		row["restart"] = map[string]any{"start": restartAt, "end": time.Now().UTC(), "ok": err == nil}
		var resetReport string
		row["post_restart_hold_observed"] = waitFor(8, func() bool {
			return conn.QueryRow(x.ctx, `SELECT r.report_id::text FROM node_generation_hold_reports r JOIN node_observations o USING(node_id,incarnation_id,report_id) WHERE r.hold_id=$1 AND o.received_at>$2 ORDER BY o.received_at LIMIT 1`, incident, restartAt).Scan(&resetReport) == nil
		})
		row["post_restart_report_id"] = resetReport
		snapshot("after_restart")
	}
	row["release_requested_at"] = time.Now().UTC()
	err = x.stack.ReleaseMatchingLeaseHold(x.ctx, "node", arm.ID)
	row["release_request_ok"] = err == nil
	var endReason string
	ended := waitFor(20, func() bool {
		return conn.QueryRow(x.ctx, `SELECT end_reason FROM node_generation_holds WHERE id=$1 AND ended_at IS NOT NULL`, incident).Scan(&endReason) == nil
	})
	row["ended"], row["end_reason"] = ended, endReason
	snapshot("recovery")
	local, err := x.stack.LocalLeaseReadback(x.ctx, "node")
	row["local_lease"], row["local_lease_available"] = local, err == nil
	row["recovered_counted"] = x.proof(x.a1)
	if !ended || endReason != "generation_matched" {
		row["reason"] = "accepted generation_matched recovery unavailable"
		return false
	}
	return true
}

