func (e *Engine) observe(ctx context.Context) error {
	if !e.enrolled || e.nodeID == uuid.Nil {
		return nil
	}
	wall := e.clock.Wall()
	interval := time.Duration(e.cfg.ObservationSeconds) * time.Second
	e.updateStaleHold()
	state := e.observationState()
	due := e.lastObs.IsZero() || wall.Sub(e.lastObs) >= interval || e.serving != e.lastServing || state != e.lastObservationState
	if !due || e.outboxFull {
		return nil
	}
	// Retain the first deciding body through backoff. Repeated copies of the
	// same pending state add no evidence; transitions always get their own ID.
	var rep api.ObservationReport
	if state == e.lastObservationState {
		items, err := e.store.Pending(ctx)
		if err != nil {
			return err
		}
		if len(items) > 0 {
			// Keep ordinary dedup free of report/journal reads. Only a waiting
			// recovery might need a new body at this unchanged state.
			if !e.closedRecoveryRenewal.armed || e.closedRecoveryRenewal.reportID != uuid.Nil {
				return nil
			}
			rep, err = e.report(ctx, wall.UTC())
			if err != nil {
				return err
			}
			if !e.canBindRecoveryReport(rep) {
				return nil
			}
		}
	}
	if rep.ReportId == uuid.Nil {
		var err error
		rep, err = e.report(ctx, wall.UTC())
		if err != nil {
			return err
		}
	}
	raw, err := json.Marshal(rep)
	if err != nil {
		return err
	}
	if err := e.store.Enqueue(ctx, rep.ReportId, raw, wall.UTC()); err != nil {
		e.storageOK = false
		return err
	}
	dueReason := e.observationDueReason(state, e.canBindRecoveryReport(rep))
	e.noteRecoveryReport(rep)
	e.log.Info(observationEnqueued, "report_id", rep.ReportId.String(),
		"observed_at", rep.ObservedAt.UTC().Format(time.RFC3339Nano), "due_reason", dueReason)
	e.lastObs = wall
	e.lastServing = e.serving
	e.lastObservationState = state
	return nil
}

func (e *Engine) report(ctx context.Context, at time.Time) (api.ObservationReport, error) {
	id, err := uuid.NewV7()
	if err != nil {
		return api.ObservationReport{}, err
	}
	appliedGen := presence.NewNullNullable[decstr.U64]()
	appliedBind := presence.NewNullNullable[decstr.U64]()
	appliedPol := presence.NewNullNullable[api.PolicyRefs]()
	if !e.identityFrozen && !e.freezeUncertain && e.appliedGen > 0 {
		appliedGen = presence.NewNullableWithValue(decstr.U64(e.appliedGen))
		if s := e.appliedSnapshot; s != nil && uint64(s.Generation) == e.appliedGen {
			appliedBind = presence.NewNullableWithValue(s.BindingRevision)
			appliedPol = presence.NewNullableWithValue(s.PolicyRefs)
		}
	}
	release := presence.NewNullNullable[uuid.UUID]()
	if rid := e.cfg.ReleaseUUID(); rid != uuid.Nil {
		release = presence.NewNullableWithValue(rid)
	}
	lastGood := presence.NewNullNullable[uuid.UUID]()
	if e.appliedGen > 0 {
		lastGood = release
	}
	exp := presence.NewNullNullable[time.Time]()
	lid := presence.NewNullNullable[uuid.UUID]()
	if e.lease != nil {
		exp = presence.NewNullableWithValue(e.lease.ExpiresAt.UTC())
		lid = presence.NewNullableWithValue(e.lease.LeaseId)
	}
	d := e.reportingDecision()
	reasons := d.Reasons
	if reasons == nil {
		reasons = []api.ForwardingBlockReason{}
	}
	errs := slices.Clone(d.Errors)
	if errs == nil {
		errs = []api.NodeError{}
	}
	checks := slices.Clone(d.Checks)
	if checks == nil {
		checks = []api.NodeCheck{}
	}
	backend := api.ObservationReportNetbirdBackendUnknown
	switch e.cfg.NetbirdBackend {
	case "kernel":
		backend = api.ObservationReportNetbirdBackendKernel
	case "userspace":
		backend = api.ObservationReportNetbirdBackendUserspace
	}
	rep := api.ObservationReport{
		AgentVersion:            e.cfg.AgentRelease,
		AppliedBindingRevision:  appliedBind,
		AppliedConfigGeneration: appliedGen,
		AppliedPolicyRefs:       appliedPol,
		BootId:                  e.bootID,
		Checks:                  checks,
		CurrentReleaseId:        release,
		DataHealth:              reportedHealth(d.DataHealth),
		Errors:                  errs,
		ForwardingBlockReasons:  reasons,
		LastGoodReleaseId:       lastGood,
		MemberForwardingEnabled: e.serving,
		NodeId:                  e.nodeID,
		NodeIncarnationId:       e.incID,
		ObservedAt:              at,
		ProvisioningState:       d.Provisioning,
		ReportId:                id,
		SafetyStatus:            d.Safety,
	}
	rep.Lease.ExpiresAt = exp
	rep.Lease.LeaseId = lid
	rep.Netbird.Backend = backend
	rep.Netbird.PeerId = presence.NewNullNullable[string]()
	rep.Netbird.Version = presence.NewNullNullable[string]()
	e.attachServingRead(&rep)
	e.attachContainment(&rep, at)
	e.attachStaleHold(&rep)
	if f := e.failedCandidate; f != nil {
		err := f.Error
		err.Stage = "apply_candidate"
		err.Message = fmt.Sprintf("candidate_generation=%d verified=false", f.Generation)
		rep.Errors = append(rep.Errors, err)
	}
	e.attachUsage(ctx, &rep)
	e.attachUpdate(ctx, &rep)
	if e.dnsEv != nil {
		rep.DnsPolicyEvidence = presence.NewNullableWithValue(*e.dnsEv)
	}
	return rep, nil
}

// The ACK describes the last completed Apply or baseline. Keep its document
// refs even when a newer desired document has replaced the live input. This is
// observation provenance, never authorization to serve or to adopt a model.
type appliedSnapshot struct {
	Generation      decstr.U64     `json:"generation"`
	BindingRevision decstr.U64     `json:"binding_revision"`
	PolicyRefs      api.PolicyRefs `json:"policy_refs"`
}

func snapshotOf(ds *api.DesiredState) appliedSnapshot {
	return appliedSnapshot{ds.ConfigGeneration, ds.BindingRevision, ds.PolicyRefs}
}

func (e *Engine) loadAppliedSnapshot(ctx context.Context) error {
	raw, ok, err := e.store.Meta(ctx, agentstore.AppliedSnapshotKey)
	if err != nil {
		return err
	}
	if ok {
		var s appliedSnapshot
		if err := json.Unmarshal([]byte(raw), &s); err != nil {
			return err
		}
		if uint64(s.Generation) == e.appliedGen {
			e.appliedSnapshot = &s
		}
	} else if e.appliedGen > 0 && e.desired != nil && uint64(e.desired.ConfigGeneration) == e.appliedGen {
		// Upgrade: only an authenticated matching document can reconstruct
		// the old ACK. A newer document cannot supply missing historical refs.
		s := snapshotOf(e.desired)
		raw, err := json.Marshal(s)
		if err != nil {
			return err
		}
		if err := e.store.MarkAppliedSnapshot(ctx, e.appliedGen, string(raw)); err != nil {
			return err
		}
		e.appliedSnapshot = &s
	}
	return nil
}

// attachUpdate reads the updater journal once for this report. A null
// generation (no file, no recorded job, or a snapshot error) leaves the
// update members null. The read is not cached and does not fail the report.
// current_release_id defaults to the running binary. Only a completed local
// switch or rollback with a valid job ID can override it from the journal.
func (e *Engine) attachUpdate(ctx context.Context, rep *api.ObservationReport) {
	rep.Update.Generation = presence.NewNullNullable[decstr.U64]()
	rep.Update.JobId = presence.NewNullNullable[uuid.UUID]()
	rep.Update.Stage = presence.NewNullNullable[api.UpdateStage]()
	rep.Update.State = presence.NewNullNullable[api.UpdateJobState]()
	if e.cfg.UpdaterJournal == "" {
		return
	}
	snap, err := updatejournal.Snapshot(ctx, e.cfg.UpdaterJournal)
	e.noteUpdateSnapshot(err)
	if err != nil || snap.Generation == nil {
		return
	}
	rep.Update.Generation = presence.NewNullableWithValue(*snap.Generation)
	if id, perr := uuid.Parse(snap.JobID); perr == nil && id != uuid.Nil {
		rep.Update.JobId = presence.NewNullableWithValue(id)
	}
	if stage := api.UpdateStage(snap.Stage); stage.Valid() {
		rep.Update.Stage = presence.NewNullableWithValue(stage)
	}
	if state := api.UpdateJobState(snap.State); state.Valid() {
		rep.Update.State = presence.NewNullableWithValue(state)
	}
	current := presence.NewNullableWithValue(e.cfg.ReleaseUUID())
	_, jobErr := rep.Update.JobId.Get()
	if jobErr == nil && (snap.JournalStage == updatejournal.StageLocallySucceeded || snap.JournalStage == updatejournal.StageRolledBack) {
		if id, perr := uuid.Parse(snap.CurrentRelease); perr == nil && id != uuid.Nil {
			current = presence.NewNullableWithValue(id)
		}
	}
	last := presence.NewNullNullable[uuid.UUID]()
	if id, perr := uuid.Parse(snap.LastGoodRelease); perr == nil && id != uuid.Nil {
		last = presence.NewNullableWithValue(id)
	}
	rep.CurrentReleaseId = current
	rep.LastGoodReleaseId = last
}

func (e *Engine) noteUpdateSnapshot(err error) {
	reason := updateSnapshotReason(err)
	if reason == e.updateSnapReason {
		return
	}
	e.updateSnapReason = reason
	if reason == "" || e.log == nil {
		return
	}
	e.log.Warn("updater journal snapshot", "reason", reason)
}

// updateSnapshotReason is a short class. It is safe to log. Snapshot errors
// can carry a path or a schema number, and those stay out of the log.
func updateSnapshotReason(err error) string {
	if err == nil {
		return ""
	}
	switch {
	case errors.Is(err, os.ErrNotExist):
		return "missing"
	case errors.Is(err, context.Canceled):
		return "canceled"
	case errors.Is(err, context.DeadlineExceeded):
		return "deadline"
	}
	msg := err.Error()
	switch {
	case strings.Contains(msg, "unsupported snapshot schema"):
		return "unsupported_schema"
	case strings.Contains(msg, "regular database file"):
		return "not_a_file"
	default:
		return "unreadable"
	}
}

func reportedHealth(h api.DataHealth) api.DataHealth {
	if !h.Valid() {
		return api.DataHealthUnknown
	}
	return h
}

func (e *Engine) flush(ctx context.Context) error {
	if e.clock.Mono() < e.observationRetryAt {
		return nil
	}
	items, err := e.store.Pending(ctx)
	if err != nil {
		e.storageOK = false
		return err
	}
	if e.observationAttempts == nil {
		e.observationAttempts = make(map[uuid.UUID]uint64)
	}
	for id := range e.observationAttempts {
		if !slices.ContainsFunc(items, func(item agentstore.OutboxItem) bool { return item.ReportID == id }) {
			delete(e.observationAttempts, id)
		}
	}
	e.outboxFull = len(items) >= 32
	for _, item := range items {
		if err := controlContext(ctx).Err(); err != nil {
			return err
		}
		var rep api.ObservationReport
		if err := json.Unmarshal(item.Payload, &rep); err != nil {
			_ = e.store.MarkConflict(ctx, item.ReportID)
			continue
		}
		if e.identityFrozen && e.freezeDurable && (rep.MemberForwardingEnabled || !rep.AppliedConfigGeneration.IsNull()) {
			_ = e.store.MarkConflict(ctx, item.ReportID)
			continue
		}
		// Persist uncertainty before sending. A process can die after central
		// accepts a freeze but before the response reaches local storage.
		if err := e.store.BumpAttempt(ctx, item.ReportID, "in_flight"); err != nil {
			e.storageOK = false
			return err
		}
		if e.submitObservation(ctx, item.ReportID, rep) {
			return nil
		}
	}
	remaining, err := e.store.Pending(ctx)
	if err != nil {
		return err
	}
	e.freezeUncertain = false
	for _, item := range remaining {
		if item.Attempts > 0 {
			e.freezeUncertain = true
		}
	}
	return nil
}

// submitObservation returns whether flush must stop after this one request.
func (e *Engine) submitObservation(ctx context.Context, id uuid.UUID, rep api.ObservationReport) bool {
	// The durable attempts field is an uncertainty marker: a retryable failure
	// increments it twice. Keep diagnostics separate without changing the outbox.
	e.observationAttempts[id]++
	attempt := e.observationAttempts[id]
	started, timer := e.clock.Wall().UTC(), time.Now()
	accepted, err := e.client.Observe(controlContext(ctx), id, rep)
	elapsed := time.Since(timer)
	var retryAt time.Time
	defer func() { e.logObservationSubmission(id, attempt, started, elapsed, accepted, err, retryAt) }()
	if err == nil {
		e.observationFailures, e.observationRetryAt = 0, 0
		if accepted.IdentityFrozen != nil && *accepted.IdentityFrozen {
			e.freezeIdentity(ctx)
			if !e.freezeDurable {
				return true
			}
		}
		e.acceptRecoveryReport(rep, accepted)
		if serr := e.store.MarkAccepted(ctx, id, e.clock.Wall().UTC()); serr != nil {
			e.storageOK = false
		}
		return false
	}
	if isRevoked(err) {
		e.markRevoked(ctx)
		return true
	}
	var se *controlclient.StatusError
	if errors.As(err, &se) && (se.Status == 409 || se.Status == 422) {
		_ = e.store.MarkConflict(ctx, id)
		return false
	}
	_ = e.store.BumpAttempt(ctx, id, safeErr(err))
	e.observationFailures++
	wait := time.Second
	for i := 1; i < e.observationFailures && wait < 30*time.Second; i++ {
		wait *= 2
	}
	wait = min(time.Minute, wait+observationJitter(wait))
	if se != nil {
		wait = max(wait, se.RetryAfter)
	}
	e.observationRetryAt = e.clock.Mono() + wait
	retryAt = e.clock.Wall().Add(wait)
	return true // One failed request per slot, even with a full outbox.
}

func observationJitter(wait time.Duration) time.Duration {
	span := wait / 10
	if span <= 0 {
		return 0
	}
	// Nanosecond ranges need more than 16 bits of entropy; otherwise every
	// node retries within a few microseconds of the same lower bound.
	var b [8]byte
	if _, err := rand.Read(b[:]); err != nil {
		return 0
	}
	return time.Duration(binary.LittleEndian.Uint64(b[:])%uint64(2*span+1)) - span
}

// Timestamps and read-at detail change every tick. The semantic transition
// includes every check status/code and block reason, including provisional.
func (e *Engine) observationState() string {
	d := e.reportingDecision()
	type check struct {
		Name   api.NodeCheckName
		Status api.HealthCheckStatus
		Code   string
	}
	cs := make([]check, 0, len(d.Checks))
	for _, c := range d.Checks {
		code, _ := c.ErrorCode.Get()
		cs = append(cs, check{c.Name, c.Status, string(code)})
	}
	// A rejected candidate is not an applied ACK. Keep its transition even
	// while older bodies await retry. Exclude read times/diagnostic durations
	// so identical pending evidence is still coalesced.
	var candidate uint64
	var code api.ErrorCode
	if f := e.failedCandidate; f != nil {
		candidate, code = f.Generation, f.Error.Code
	}
	var readGeneration uint64
	var verified bool
	if r := e.servingRead; r != nil {
		readGeneration, verified = r.Generation, r.Verified
	}
	var containment any
	if c := e.containment; c != nil {
		v := *c
		v.ReadAt = time.Time{}
		containment = []any{c.Generation, v}
	}
	b, _ := json.Marshal([]any{e.serving, e.appliedGen, d.Provisioning, d.Safety, d.Reasons, cs,
		candidate, code, readGeneration, verified, containment, e.staleHold.steps > 0, e.staleHold.alarm})
	return string(b)
}

// An Apply failure can precede the verifier. Report the attempted generation
// without pretending that a missing verifier read supplied fresh tc evidence.
type failedCandidate struct {
	Generation uint64
	Error      api.NodeError
}

// A cached serving decision can precede a failed local persistence/withdrawal.
// Report the current cause when one exists. The zero decision before the first
// evaluation has no checks and legitimately retains the heartbeat's "-".
func (e *Engine) reportingDecision() Decision {
	d := e.decision
	if !e.serving && len(d.Reasons) == 0 && len(d.Checks) != 0 {
		current := Decide(e.input())
		if len(current.Reasons) != 0 {
			current.Errors = append(current.Errors, d.Errors...)
			return current
		}
	}
	return d
}

package agent

import (
	"github.com/TED-H-com/Freedom-VPN/pkg/api"
	"github.com/google/uuid"
)

// D-157 is one opportunity per verified closed Apply, not per empty lease or
// report. It is process-local: restart does not recreate a closed Apply receipt.
type recoveryRenewal struct {
	armed    bool
	reportID uuid.UUID
	accepted bool
}

func (e *Engine) recoveryRenewalEligible() bool {
	return e.closedRecoveryHeld && !e.serving && e.applyError == nil &&
		!e.revoked && !e.identityFrozen && !e.freezeUncertain && e.storageOK &&
		!e.quarantinePending && !e.memberPathPending && !e.dependencyMissing &&
		e.appliedGen > 0 && e.desiredOK && !e.desiredExpired && e.desired != nil &&
		uint64(e.desired.ConfigGeneration) == e.appliedGen && e.leaseGrantless() &&
		!e.leaseBehindApplied()
}

// Bind to a newly queued report from this recovery. An old queued report, even
// at the same generation, cannot arm a later recovery's opportunity.
func (e *Engine) noteRecoveryReport(rep api.ObservationReport) {
	if e.canBindRecoveryReport(rep) {
		e.closedRecoveryRenewal.reportID = rep.ReportId
	}
}

// The pending-outbox exception and the binding use this exact predicate. An
// armed recovery can remain unbindable; it must not disable ordinary dedup.
func (e *Engine) canBindRecoveryReport(rep api.ObservationReport) bool {
	r := &e.closedRecoveryRenewal
	if !r.armed || r.reportID != uuid.Nil || !e.recoveryRenewalEligible() {
		return false
	}
	gen, err := rep.AppliedConfigGeneration.Get()
	if err != nil || uint64(gen) != e.appliedGen || rep.MemberForwardingEnabled ||
		rep.SafetyStatus != api.SafetyStatusPassed || rep.ProvisioningState != api.ProvisioningStateReady ||
		rep.Netbird.Backend != api.ObservationReportNetbirdBackendKernel || !rep.Netbird.PeerId.IsNull() {
		return false
	}
	// These are central's synchronous readiness evidence requirements. A failed
	// meter path is never the D-067 awaiting-grants exception.
	internet, awaiting := false, false
	for _, reason := range rep.ForwardingBlockReasons {
		awaiting = awaiting || reason == api.ForwardingBlockReasonAwaitingMemberGrants
	}
	for _, check := range rep.Checks {
		if check.Name == api.NodeCheckNameInternetOnly {
			internet = check.Status == api.HealthCheckStatusPassed
		}
		if check.Name == api.NodeCheckNameMeterPath && check.Status == api.HealthCheckStatusFailed {
			return false
		}
	}
	for _, err := range rep.Errors {
		switch err.Code {
		case api.ErrorCodeISOLATIONPOLICYINVALID, api.ErrorCodeISOLATIONBASELINEMISSING, api.ErrorCodeMETERPATHINVALID:
			return false
		}
	}
	return internet && awaiting
}

func (e *Engine) acceptRecoveryReport(rep api.ObservationReport, accepted api.ObservationAccepted) {
	r := &e.closedRecoveryRenewal
	if r.armed && r.reportID != uuid.Nil && rep.ReportId == r.reportID &&
		accepted.ReportId == rep.ReportId && bool(accepted.Accepted) &&
		(accepted.IdentityFrozen == nil || !*accepted.IdentityFrozen) && e.recoveryRenewalEligible() {
		r.accepted = true
	}
}

func (e *Engine) earlyRecoveryRenewal() bool {
	return e.closedRecoveryRenewal.armed && e.closedRecoveryRenewal.accepted && e.recoveryRenewalEligible()
}

package agent

import (
	"context"
	"errors"
	"io"
	"net"
	"os"
	"syscall"
	"time"

	"github.com/TED-H-com/Freedom-VPN/node/internal/controlclient"
	"github.com/TED-H-com/Freedom-VPN/pkg/api"
	"github.com/google/uuid"
)

// These record names and field names are an operator/harness interface.
const observationEnqueued = "observation enqueued"
const observationSubmission = "observation submission"

func (e *Engine) observationDueReason(state string, binding bool) string {
	switch {
	case binding:
		return "closed_recovery_binding"
	case e.lastObservationState == "":
		return "first_report"
	case e.serving != e.lastServing:
		return "serving_changed"
	case state != e.lastObservationState || e.lastObs.IsZero():
		return "state_changed"
	default:
		return "interval_elapsed"
	}
}

// Only a finite error class leaves the client boundary. In particular, a
// url.Error's string can contain a URL, user info or untrusted response text.
func observationErrorClass(err error) (outcome, class string) {
	if errors.Is(err, context.DeadlineExceeded) {
		return "timeout", "deadline_exceeded"
	}
	var ne net.Error
	if errors.As(err, &ne) && ne.Timeout() {
		return "timeout", "network_timeout"
	}
	switch {
	case errors.Is(err, context.Canceled):
		return "transport_error", "canceled"
	case errors.Is(err, syscall.ECONNREFUSED):
		return "transport_error", "connection_refused"
	case errors.Is(err, syscall.ECONNRESET):
		return "transport_error", "connection_reset"
	case errors.Is(err, io.EOF), errors.Is(err, io.ErrUnexpectedEOF):
		return "transport_error", "connection_closed"
	}
	var dns *net.DNSError
	if errors.As(err, &dns) {
		return "transport_error", "dns"
	}
	var op *net.OpError
	if errors.As(err, &op) {
		return "transport_error", "network"
	}
	return "transport_error", "other"
}

func (e *Engine) logObservationSubmission(id uuid.UUID, attempt uint64, started time.Time, elapsed time.Duration, accepted api.ObservationAccepted, err error, retryAt time.Time) {
	outcome, class, code, status := "accepted", "", "", 202
	acceptedIDs := []uuid.UUID{}
	retryAfter := time.Duration(0)
	if err == nil {
		if bool(accepted.Accepted) {
			acceptedIDs = append(acceptedIDs, accepted.ReportId)
		} else {
			outcome = "unconfirmed_response"
		}
	} else {
		status = 0
		var se *controlclient.StatusError
		if errors.As(err, &se) {
			outcome, status, retryAfter = "rejected", se.Status, se.RetryAfter
			code = se.Code
			if code != "" && !api.ErrorCode(code).Valid() {
				code = "unknown"
			}
		} else {
			outcome, class = observationErrorClass(err)
		}
	}
	var next any
	if !retryAt.IsZero() {
		next = retryAt.UTC().Format(time.RFC3339Nano)
	}
	e.log.Info(observationSubmission,
		"report_ids", []uuid.UUID{id}, "attempt_numbers", []uint64{attempt},
		"attempt_scope", "process", "process_id", os.Getpid(), "boot_id", e.bootID.String(),
		"started_at", started.UTC().Format(time.RFC3339Nano), "duration_ms", elapsed.Milliseconds(),
		"outcome", outcome, "accepted_report_ids", acceptedIDs, "http_status", status,
		"error_code", code, "transport_error_class", class,
		"next_retry_at", next, "retry_after_ms", retryAfter.Milliseconds())
}
